{"command": "cat > src/util.hh <<'EOF'
#pragma once
#include <string>
#include <vector>
#include <sstream>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <ctime>
#include <cctype>
#include <memory>

namespace lnav {

inline std::string fmt_str(const char *f, ...)
{
    std::vector<char> buf(256);
    va_list ap;
    va_start(ap, f);
    int n = vsnprintf(buf.data(), buf.size(), f, ap);
    va_end(ap);
    if (n >= (int)buf.size()) {
        buf.resize(n + 1);
        va_start(ap, f);
        vsnprintf(buf.data(), buf.size(), f, ap);
        va_end(ap);
    }
    return std::string(buf.data());
}

inline std::vector<std::string> split(const std::string &s, char sep)
{
