    out += "  error: " + e.error + "\n";
    if (!e.reason.empty()) {
        out += " reason: " + e.reason + "\n";
    }
    if (!e.location.empty()) {
        out += " --> " + e.location + "\n";
        for (auto &l : e.context) {
            std::string line = l;
            if (line.size() < 40) line += std::string(40 - line.size(), ' ');
            out += " | " + line + "\n";
        }
    }
    if (!e.note_header.empty()) {
        out += " = " + e.note_header + "\n";
        for (auto &item : e.note_items) {
            out += "           " + item.first + " - " + item.second + "\n";
        }
    } else if (!e.help_synopsis.empty()) {
        out += " = help: " + e.help_synopsis + "\n";
        out += "         " + std::string(70, '=') + "\n";
        for (auto &l : e.help_desc) {
            out += "           " + l + "\n";
        }
        for (auto &l : e.help_raw) {
            out += l + "\n";
        }
    }
    fputs(out.c_str(), stderr);
}

void report_simple(const std::string &err, const std::string &reason)
{
    DisplayError e;
    e.error = err;
    e.reason = reason;
    report_error(e);
}

