EOF
cat > src/help.cc <<'EOF'
#include "help.hh"
#include "help_data.hh"
#include "main_help_data.hh"
#include "paths.hh"

namespace lnav {

static std::vector<std::string> g_help_lines;
static std::map<std::string, CmdDoc> g_docs;

std::string render_help(const char *const *lines, bool trailing_nl)
{
    std::string out;
    for (int i = 0; lines[i] != nullptr; i++) {
        out += lines[i];
        out += '\n';
    }
    (void)trailing_nl;
    return out;
}

void init_help()
{
    if (!g_help_lines.empty()) return;
    for (int i = 0; lnav_help_lines[i] != nullptr; i++) {
        g_help_lines.push_back(lnav_help_lines[i]);
    }
    // Parse the command reference
    size_t n = g_help_lines.size();
    for (size_t i = 0; i < n; i++) {
        const std::string &l = g_help_lines[i];
        if (l.empty() || l[0] != ':') continue;
        if (i + 1 >= n) break;
        const std::string &under = g_help_lines[i + 1];
        if (under.empty() || under.find_first_not_of('=') != std::string::npos) continue;
        if (under.size() != 70) continue;
        // Extract command name
        std::string word = l.substr(1);
        size_t sp = word.find(' ');
        std::string name = sp == std::string::npos ? word : word.substr(0, sp);
        CmdDoc doc;
        doc.name = name;
        doc.synopsis = l;
        size_t j = i + 2;
        while (j < n && !g_help_lines[j].empty()) {
            const std::string &dl = g_help_lines[j];
            if (dl == "Parameter" || dl == "Parameters" || dl == "See Also" ||
                dl == "Examples" || dl == "Example") {
                break;
            }
            if (dl.size() < 2 || dl[0] != ' ' || dl[1] != ' ') break;
            doc.desc.push_back(dl);
            j++;
        }
        if (!doc.desc.empty()) {
            g_docs[name] = doc;
        }
    }
}

const std::vector<std::string> &help_lines()
{
    init_help();
    return g_help_lines;
}

const std::map<std::string, CmdDoc> &command_docs()
{
    init_help();
    return g_docs;
}

const CmdDoc *find_doc(const std::string &name)
{
    init_help();
    auto iter = g_docs.find(name);
    if (iter == g_docs.end()) return nullptr;
    return &iter->second;
}

void print_internal_help()
{
    init_help();
    std::string out;
    for (auto &l : g_help_lines) {
        out += l;
        out += '\n';
    }
    fputs(out.c_str(), stdout);
}

static std::string expand(const std::string &line, const std::string &prog)
{
    std::string out;
    for (size_t i = 0; i < line.size(); i++) {
        if (line[i] == '\001') {
            size_t j = line.find('\001', i + 1);
            std::string key = line.substr(i + 1, j - i - 1);
            if (key == "BIN") {
                out += prog;
            } else if (key == "FMTDIRS") {
                bool first = true;
                for (auto &d : get_format_dirs()) {
                    if (!first) out += "\n    \U0001F4C2 ";
                    out += d;
                    first = false;
                }
            } else if (key == "CONFDIR") {
                out += get_config_dir();
            } else if (key == "TMPDIR") {
                out += get_tmp_dir();
            }
            if (j == std::string::npos) break;
            i = j;
        } else {
            out += line[i];
        }
    }
    return out;
}

void print_help(const Options &opts)
{
    (void)opts;
    const char *argv0 = g_prog_name;
    std::string prog = argv0;
    for (int i = 0; main_help_lines[i] != nullptr; i++) {
        std::string l = expand(main_help_lines[i], prog);
        fputs(l.c_str(), stdout);
        fputc('\n', stdout);
    }
}

void print_version()
{
    printf("lnav %s\n", LNAV_VERSION);
}

void print_tty_error()
{
    DisplayError e;
    e.error = "unable to display interactive text UI";
    e.reason = "stdout is not a TTY";
    e.help_raw.push_back(" = help: pass the -n option to run lnav in headless mode or don't redirect stdout");
    report_error(e);
}

}  // namespace lnav
