#pragma once
#include "util.hh"
#include <ctime>
#include <optional>

namespace lnav {

// microseconds since the epoch (UTC)
typedef long long usecs_t;

inline usecs_t to_usecs(const struct tm &tm, long usec)
{
    struct tm copy = tm;
    time_t t = timegm(&copy);
    return (usecs_t)t * 1000000LL + usec;
}

struct tm utc_break(usecs_t us);

// Parse "2024-01-01T10:00:00.000Z" style timestamps.  Returns the number of
// characters consumed or 0 on failure.
struct TSResult {
    usecs_t usecs = 0;
    int consumed = 0;
    bool has_tz = false;
    bool has_year = false;
    bool has_date = false;
};

std::optional<TSResult> parse_timestamp(const std::string &s, bool assume_utc_today);

std::string format_time_iso(usecs_t us);

}  // namespace lnav
