static int num(const std::string &s, size_t pos, size_t n)
{
    int v = 0;
    for (size_t i = 0; i < n; i++) v = v * 10 + (s[pos + i] - '0');
    return v;
}

std::optional<TSResult> parse_timestamp(const std::string &s, bool assume_utc_today)
{
    TSResult res;
    size_t i = 0;
    struct tm tm;
    memset(&tm, 0, sizeof(tm));
    long usec = 0;
    int tz_offset_secs = 0;
    bool has_tz = false;
    bool has_year = false, has_date = false;

    // Try ISO-style YYYY-MM-DD or YYYY/MM/DD
    size_t start = i;
    if (is_digits(s, 0, 4) && (s.size() > 6) && s[4] == '-' && s[7] == '-') {
        tm.tm_year = num(s, 0, 4) - 1900;
        tm.tm_mon = num(s, 5, 2) - 1;
        tm.tm_mday = num(s, 8, 2);
        i = 10;
        has_year = true;
        has_date = true;
        if (i >= s.size() || (!isdigit((unsigned char)s[i]) && s[i] != 'T' && s[i] != ' ')) {
            // date only
            res.usecs = to_usecs(tm, 0);
            res.consumed = (int)i;
            res.has_tz = false;
            res.has_year = true;
            res.has_date = true;
            return res;
        }
        if (s[i] == 'T' || s[i] == ' ') i++;
        goto time_part;
    }
    if (is_digits(s, 0, 4) && s.size() > 7 && s[4] == '/' && s[7] == '/') {
        tm.tm_year = num(s, 0, 4) - 1900;
        tm.tm_mon = num(s, 5, 2) - 1;
        tm.tm_mday = num(s, 8, 2);
        i = 10;
        has_year = true;
        has_date = true;
        if (s[i] != ' ') return std::nullopt;
        i++;
        goto time_part;
    }
    // HH:MM or HH:MM:SS (time of day only)
    if (is_digits(s, 0, 2) && s.size() > 2 && s[2] == ':') {
        time_t now = time(nullptr);
        struct tm now_tm;
        gmtime_r(&now, &now_tm);
        tm.tm_year = now_tm.tm_year;
        tm.tm_mon = now_tm.tm_mon;
        tm.tm_mday = now_tm.tm_mday;
        goto time_part;
    }
    // DD/MM/YYYY HH:MM[:SS]
    if (is_digits(s, 0, 2) && s.size() > 8 && s[2] == '/' && s[5] == '/' && is_digits(s, 6, 4)) {
        tm.tm_mday = num(s, 0, 2);
        tm.tm_mon = num(s, 3, 2) - 1;
        tm.tm_year = num(s, 6, 4) - 1900;
        i = 10;
        has_year = true;
        has_date = true;
        if (s[i] != ' ') return std::nullopt;
        i++;
        goto time_part;
    }
    // Month name DD HH:MM:SS  (syslog)
    {
        static const char *months[] = {"Jan", "Feb", "Mar", "Apr", "May", "Jun",
                                       "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
        for (int m = 0; m < 12; m++) {
            size_t ml = 3;
            if (s.compare(0, ml, months[m]) == 0 && s.size() > ml &&
                (s[ml] == ' ')) {
                size_t p = ml;
                while (p < s.size() && s[p] == ' ') p++;
                if (is_digits(s, p, 2) && p + 2 < s.size() && s[p + 2] == ' ' &&
                    p + 5 < s.size() && s[p + 5] == ':') {
                    tm.tm_mon = m;
                    tm.tm_mday = num(s, p, 2);
                    i = p + 3;
                    time_t now = time(nullptr);
                    struct tm now_tm;
                    gmtime_r(&now, &now_tm);
                    tm.tm_year = now_tm.tm_year;
                    has_date = true;
                    has_year = false;
                    goto time_part;
                }
            }
        }
    }
    (void)start;
    (void)assume_utc_today;
    return std::nullopt;

time_part:
    if (!is_digits(s, i, 2)) return std::nullopt;
    tm.tm_hour = num(s, i, 2);
    i += 2;
    if (i + 1 < s.size() && s[i] == ':') {
        i++;
        if (!is_digits(s, i, 2)) return std::nullopt;
        tm.tm_min = num(s, i, 2);
        i += 2;
        if (i < s.size() && s[i] == ':') {
            i++;
            if (!is_digits(s, i, 2)) return std::nullopt;
            tm.tm_sec = num(s, i, 2);
            i += 2;
        } else if (i + 1 < s.size() && s[i] == ' ' && is_digits(s, i + 1, 2)) {
            // "10:00 30" style
            i++;
            tm.tm_sec = num(s, i, 2);
            i += 2;
        }
    } else {
        return std::nullopt;
    }
    // fractional seconds
    if (i < s.size() && (s[i] == '.' || s[i] == ',')) {
        size_t p = i + 1;
        size_t d = 0;
        while (p + d < s.size() && isdigit((unsigned char)s[p + d])) d++;
        if (d > 0) {
            std::string frac = s.substr(p, d);
            while (frac.size() < 6) frac += '0';
            if (frac.size() > 6) frac = frac.substr(0, 6);
            usec = atol(frac.c_str());
            i = p + d;
        }
    }
    // timezone
    if (i < s.size()) {
        if (s[i] == 'Z' || s[i] == 'z') {
            i++;
            has_tz = true;
        } else if ((s[i] == '+' || s[i] == '-') && i + 1 < s.size() &&
                   isdigit((unsigned char)s[i + 1])) {
            int sign = s[i] == '-' ? -1 : 1;
            size_t p = i + 1;
            int hh = 0, mm = 0;
            if (is_digits(s, p, 2) && p + 2 < s.size() && s[p + 2] == ':') {
                hh = num(s, p, 2);
                mm = num(s, p + 3, 2);
                p += 5;
            } else if (is_digits(s, p, 4)) {
                hh = num(s, p, 2);
                mm = num(s, p + 2, 2);
                p += 4;
            } else {
                return std::nullopt;
            }
            tz_offset_secs = sign * (hh * 3600 + mm * 60);
            has_tz = true;
            i = p;
        }
    }
    res.usecs = to_usecs(tm, usec) - (usecs_t)tz_offset_secs * 1000000LL;
    res.consumed = (int)i;
    res.has_tz = has_tz;
    res.has_year = has_year;
    res.has_date = has_date;
    return res;
}

std::string format_time_iso(usecs_t us)
{
    struct tm tm = utc_break(us);
    long frac = (long)(us % 1000000LL);
    char buf[64];
    snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d.%06lld",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min,
             tm.tm_sec, (long long)frac);
    return buf;
}

}  // namespace lnav
EOF
echo ok"}

