{"command": "cat > src/logfile.cc <<'EOF'
#include "logfile.hh"
#include "util.hh"

namespace lnav {

static const char *const LEVEL_WORDS[] = {
    "trace", "debug", "info", "notice", "warning", "error", "critical", "fatal",
    nullptr
};
static const char *const LEVEL_ALIASES[][2] = {
    {"warn", "warning"}, {"err", "error"}, {"alert", "critical"}, {nullptr, nullptr}
};

std::string detect_level(const std::string &body)
{
    static const char *const order[] = {
        "fatal", "critical", "alert", "warning", "warn", "error", "err",
        "notice", "debug", "trace", "info", nullptr
    };
    for (int i = 0; order[i] != nullptr; i++) {
        size_t pos = body.find(order[i]);
        if (pos == std::string::npos) continue;
        for (int j = 0; LEVEL_ALIASES[j][0] != nullptr; j++) {
            if (strcmp(order[i], LEVEL_ALIASES[j][0]) == 0) return LEVEL_ALIASES[j][1];
        }
        return order[i];
    }
    return "unknown";
}

static int month_from_name(const std::string &s)
{
    static const char *months[] = {"Jan", "Feb", "Mar", "Apr", "May", "Jun",
                                   "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
    for (int i = 0; i < 12; i++) {
        if (s.compare(0, 3, months[i]) == 0) return i;
    }
    return -1;
}

// Applies the "syslog without a year" adjustment: if the resulting time is in
// the future, assume the previous year.
static usecs_t adjust_syslog_year(usecs_t us)
{
    usecs_t now = (usecs_t)time(nullptr) * 1000000LL;
    if (us > now) {
        struct tm tm = utc_break(us);
        tm.tm_year -= 1;
        us = to_usecs(tm, (long)(us % 1000000LL));
    }
    return us;
}

// ---------------------------------------------------------------------------
// generic_log
// ---------------------------------------------------------------------------
class GenericLog : public LogFormat {
public:
    GenericLog()
    {
        name = "generic_log";
        description = "'Generic' log format";
        append_unmatched = true;
    }

    std::optional<MsgMatch> match(const std::string &line) const override
    {
        auto ts = parse_timestamp(line, true);
        if (!ts.has_value()) return std::nullopt;
        if (ts->consumed == 0) return std::nullopt;
        size_t p = ts->consumed;
        while (p < line.size() && (line[p] == ' ' || line[p] == '\t')) p++;
        std::string rest = line.substr(p);
        MsgMatch m;
        m.time = ts->usecs;
        m.has_time = true;
        m.pattern_number = 0;
        // Pattern 1: timestamp LEVEL body
        {
            size_t sp = rest.find(' ');
            if (sp != std::string::npos) {
                std::string word = rest.substr(0, sp);
                std::string lv = to_lower(word);
                bool is_level = false;
                for (int i = 0; LEVEL_WORDS[i] != nullptr; i++) {
                    if (lv == LEVEL_WORDS[i]) { is_level = true; break; }
                }
                for (int i = 0; LEVEL_ALIASES[i][0] != nullptr; i++) {
                    if (lv == LEVEL_ALIASES[i][0]) { is_level = true; break; }
                }
                if (is_level && sp + 1 <= rest.size()) {
                    m.level = lv == "warn" ? "warning" : (lv == "err" ? "error" : lv);
                    m.fields["col_0"] = rest.substr(sp + 1);
                    m.pattern_number = 1;
                    return m;
                }
            }
        }
        // Pattern 2: timestamp [LEVEL] body
        if (!rest.empty() && rest[0] == '[') {
            size_t cb = rest.find(']');
            if (cb != std::string::npos) {
                std::string lv = to_lower(trim(rest.substr(1, cb - 1)));
                bool is_level = false;
                for (int i = 0; LEVEL_WORDS[i] != nullptr; i++) {
                    if (lv == LEVEL_WORDS[i]) { is_level = true; break; }
                }
                for (int i = 0; LEVEL_ALIASES[i][0] != nullptr; i++) {
                    if (lv == LEVEL_ALIASES[i][0]) { is_level = true; break; }
                }
                if (is_level) {
                    size_t q = cb + 1;
                    while (q < rest.size() && (rest[q] == ' ' || rest[q] == '\t')) q++;
                    m.level = lv == "warn" ? "warning" : (lv == "err" ? "error" : lv);
                    m.fields["col_0"] = rest.substr(q);
                    m.pattern_number = 2;
                    return m;
                }
            }
        }
        // Pattern 5: timestamp body
        m.pattern_number = 5;
        m.fields["col_0"] = rest;
        m.level = detect_level(rest);
        return m;
    }
};

// ---------------------------------------------------------------------------
// syslog_log
// ---------------------------------------------------------------------------
class SyslogLog : public LogFormat {
public:
    SyslogLog()
    {
        name = "syslog_log";
        description = "The system logger format found on most posix systems.";
        append_unmatched = true;
    }

    std::optional<MsgMatch> match(const std::string &line) const override
    {
        auto ts = parse_timestamp(line, true);
        if (!ts.has_value() || ts->consumed == 0) return std::nullopt;
        size_t p = ts->consumed;
        // The syslog format needs a whitespace separated date
        if (p >= line.size() || line[p] != ' ') return std::nullopt;
        while (p < line.size() && line[p] == ' ') p++;
        size_t hp = p;
        while (p < line.size() && !isspace((unsigned char)line[p])) p++;
        std::string host = line.substr(hp, p - hp);
        if (host.empty()) return std::nullopt;
        while (p < line.size() && line[p] == ' ') p++;
        size_t tp = p;
        while (p < line.size() && !isspace((unsigned char)line[p])) p++;
        std::string tag = line.substr(tp, p - tp);
        std::string body;
        std::string procname, pid;
        if (p < line.size() && line[p] == ':') {
            // "procname[pid]: body"
            size_t br = tag.find('[');
            if (br != std::string::npos && tag[tag.size() - 1] == ']') {
                procname = tag.substr(0, br);
                pid = tag.substr(br + 1, tag.size() - br - 2);
            } else {
                procname = tag;
            }
            p++;
            if (p < line.size() && line[p] == ' ') p++;
            body = line.substr(p);
            if (procname.empty()) return std::nullopt;
        } else {
            return std::nullopt;
        }
        MsgMatch m;
        m.time = adjust_syslog_year(ts->usecs);
        m.has_time = true;
        m.level = "info";
        m.fields["log_hostname"] = host;
        if (!pid.empty()) m.fields["log_pid"] = pid;
        if (!procname.empty()) m.fields["log_procname"] = procname;
        m.fields["log_syslog_tag"] = tag;
        m.pattern_number = 1;
        return m;
    }
};

// ---------------------------------------------------------------------------
// access_log
// ---------------------------------------------------------------------------
class AccessLog : public LogFormat {
public:
    AccessLog()
    {
        name = "access_log";
        description = "The default web access log format for servers like Apache.";
        append_unmatched = false;
    }

    std::optional<MsgMatch> match(const std::string &line) const override
    {
        size_t p = 0;
        auto skip_ws = [&p, &line]() {
            while (p < line.size() && line[p] == ' ') p++;
        };
        auto tok = [&p, &line]() -> std::string {
            skip_ws();
            if (p < line.size() && line[p] == '"') {
                size_t e = line.find('"', p + 1);
                if (e == std::string::npos) return "";
                std::string r = line.substr(p + 1, e - p - 1);
                p = e + 1;
                return r;
            }
            if (p < line.size() && line[p] == '[') {
                size_t e = line.find(']', p + 1);
                if (e == std::string::npos) return "";
                std::string r = line.substr(p + 1, e - p - 1);
                p = e + 1;
                return r;
            }
            size_t s = p;
            while (p < line.size() && line[p] != ' ') p++;
            return line.substr(s, p - s);
        };
        std::string c_ip = tok();
        std::string ident = tok();
        std::string user = tok();
        std::string ts = tok();
        if (c_ip.empty() || ts.empty()) return std::nullopt;
        // request
        skip_ws();
        if (p >= line.size() || line[p] != '"') return std::nullopt;
        size_t qend = line.find('"', p + 1);
        if (qend == std::string::npos) return std::nullopt;
        std::string request = line.substr(p + 1, qend - p - 1);
        p = qend + 1;
        std::string status = tok();
        std::string bytes = tok();
        std::string referrer = tok();
        std::string agent = tok();
        skip_ws();
        if (p != line.size()) return std::nullopt;
        auto tsr = parse_timestamp(ts, false);
        if (!tsr.has_value()) return std::nullopt;
        MsgMatch m;
        m.time = tsr->usecs;
        m.has_time = true;
        m.level = "info";
        m.fields["c_ip"] = c_ip;
        m.fields["cs_username"] = user;
        m.fields["cs_referrer"] = referrer;
        m.fields["cs_user_agent"] = agent;
        // parse the request
        {
