        std::string tag = line.substr(tp, p - tp);
        std::string body;
        std::string procname, pid;
        if (p < line.size() && line[p] == ':') {
            // "procname[pid]: body"
            size_t br = tag.find('[');
            if (br != std::string::npos && tag[tag.size() - 1] == ']') {
                procname = tag.substr(0, br);
                pid = tag.substr(br + 1, tag.size() - br - 2);
            } else {
                procname = tag;
            }
            p++;
            if (p < line.size() && line[p] == ' ') p++;
            body = line.substr(p);
            if (procname.empty()) return std::nullopt;
        } else {
            return std::nullopt;
        }
        MsgMatch m;
        m.time = adjust_syslog_year(ts->usecs);
        m.has_time = true;
        m.level = "info";
        m.fields["log_hostname"] = host;
        if (!pid.empty()) m.fields["log_pid"] = pid;
        if (!procname.empty()) m.fields["log_procname"] = procname;
        m.fields["log_syslog_tag"] = tag;
        m.pattern_number = 1;
        return m;
    }
};

// ---------------------------------------------------------------------------
// access_log
// ---------------------------------------------------------------------------
class AccessLog : public LogFormat {
public:
    AccessLog()
    {
        name = "access_log";
        description = "The default web access log format for servers like Apache.";
        append_unmatched = false;
    }

    std::optional<MsgMatch> match(const std::string &line) const override
    {
        size_t p = 0;
        auto skip_ws = [&p, &line]() {
            while (p < line.size() && line[p] == ' ') p++;
        };
        auto tok = [&p, &line]() -> std::string {
            skip_ws();
            if (p < line.size() && line[p] == '"') {
                size_t e = line.find('"', p + 1);
                if (e == std::string::npos) return "";
                std::string r = line.substr(p + 1, e - p - 1);
                p = e + 1;
                return r;
            }
            if (p < line.size() && line[p] == '[') {
                size_t e = line.find(']', p + 1);
                if (e == std::string::npos) return "";
                std::string r = line.substr(p + 1, e - p - 1);
                p = e + 1;
                return r;
            }
            size_t s = p;
            while (p < line.size() && line[p] != ' ') p++;
            return line.substr(s, p - s);
        };
        std::string c_ip = tok();
        std::string ident = tok();
        std::string user = tok();
        std::string ts = tok();
        if (c_ip.empty() || ts.empty()) return std::nullopt;
        // request
        skip_ws();
        if (p >= line.size() || line[p] != '"') return std::nullopt;
        size_t qend = line.find('"', p + 1);
        if (qend == std::string::npos) return std::nullopt;
        std::string request = line.substr(p + 1, qend - p - 1);
        p = qend + 1;
        std::string status = tok();
        std::string bytes = tok();
        std::string referrer = tok();
        std::string agent = tok();
        skip_ws();
        if (p != line.size()) return std::nullopt;
        auto tsr = parse_timestamp(ts, false);
        if (!tsr.has_value()) return std::nullopt;
        MsgMatch m;
        m.time = tsr->usecs;
        m.has_time = true;
        m.level = "info";
        m.fields["c_ip"] = c_ip;
        m.fields["cs_username"] = user;
        m.fields["cs_referrer"] = referrer;
        m.fields["cs_user_agent"] = agent;
        // parse the request
        {
            size_t sp = request.find(' ');
            if (sp != std::string::npos) {
                m.fields["cs_method"] = request.substr(0, sp);
                size_t sp2 = request.find(' ', sp + 1);
                if (sp2 != std::string::npos) {
                    std::string uri = request.substr(sp + 1, sp2 - sp - 1);
                    size_t qm = uri.find('?');
                    if (qm != std::string::npos) {
                        m.fields["cs_uri_stem"] = uri.substr(0, qm);
                        m.fields["cs_uri_query"] = uri.substr(qm + 1);
                    } else {
                        m.fields["cs_uri_stem"] = uri;
                    }
                    m.fields["cs_version"] = request.substr(sp2 + 1);
                } else {
                    m.fields["cs_uri_stem"] = request.substr(sp + 1);
                }
            }
        }
        m.fields["sc_status"] = status;
        m.fields["sc_bytes"] = bytes;
        m.pattern_number = 1;
        return m;
    }
};

const std::vector<std::shared_ptr<LogFormat>> &all_formats()
{
    static std::vector<std::shared_ptr<LogFormat>> formats = []() {
        std::vector<std::shared_ptr<LogFormat>> v;
        v.push_back(std::make_shared<AccessLog>());
        v.push_back(std::make_shared<SyslogLog>());
        v.push_back(std::make_shared<GenericLog>());
        return v;
    }();
    return formats;
}

std::shared_ptr<LogFormat> find_format(const std::string &name)
{
    for (auto &f : all_formats()) {
        if (f->name == name) return f;
    }
    return nullptr;
}

std::shared_ptr<LogFile> load_file(const std::string &path, bool &ok)
{
    ok = false;
    FILE *fp = fopen(path.c_str(), "rb");
    if (fp == nullptr) return nullptr;
    std::vector<std::string> lines;
    std::string cur;
    char buf[65536];
    size_t n;
    bool last_was_newline = true;
    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
        for (size_t i = 0; i < n; i++) {
            char c = buf[i];
            if (c == '\n') {
                if (!cur.empty() && cur.back() == '\r') cur.pop_back();
                lines.push_back(cur);
                cur.clear();
                last_was_newline = true;
            } else {
                cur += c;
                last_was_newline = false;
            }
        }
    }
    fclose(fp);
    if (!cur.empty()) lines.push_back(cur);
    (void)last_was_newline;
    auto lf = std::make_shared<LogFile>();
    lf->path = path;
    lf->lines = lines;
    ok = true;

    if (lines.empty()) {
        // An empty file is not a text file
        return lf;
    }

    // Detect the format: the first line that matches a non-generic format
    // wins, otherwise the first line that matches the generic format.
    std::shared_ptr<LogFormat> generic;
    for (auto &f : all_formats()) {
        if (f->name == "generic_log") generic = f;
    }
    for (auto &line : lines) {
        for (auto &f : all_formats()) {
            if (f->name == "generic_log") continue;
            if (f->match(line).has_value()) {
                lf->format = f;
                break;
            }
        }
        if (lf->format != nullptr) break;
        if (generic != nullptr && generic->match(line).has_value()) {
            lf->format = generic;
        }
    }
    if (lf->format == nullptr) {
        lf->is_text = true;
        return lf;
    }

    // Parse the messages
    bool first_unmatched = true;
    for (size_t i = 0; i < lines.size(); i++) {
        auto m = lf->format->match(lines[i]);
        if (m.has_value()) {
            LogMessage msg;
            msg.file_index = 0;
            msg.line_number = (int)i;
            msg.num_lines = 1;
            msg.time = m->time;
            msg.has_time = m->has_time;
            msg.level = m->level;
            msg.pattern_number = m->pattern_number;
            msg.fields = m->fields;
            lf->messages.push_back(msg);
            first_unmatched = false;
        } else {
            if (!lf->messages.empty() && lf->format->append_unmatched) {
                lf->messages.back().num_lines++;
            } else {
                LogMessage msg;
                msg.line_number = (int)i;
                msg.time = 0;
                msg.has_time = false;
                msg.level = first_unmatched ? "unknown" : "invalid";
                lf->messages.push_back(msg);
                first_unmatched = false;
            }
        }
    }
    return lf;
}

