namespace lnav {

DbView::~DbView()
{
    if (db != nullptr) sqlite3_close(db);
}

bool DbView::open()
{
    if (db != nullptr) return true;
    int rc = sqlite3_open(":memory:", &db);
    if (rc != SQLITE_OK) {
        last_error = db != nullptr ? sqlite3_errmsg(db) : "out of memory";
        return false;
    }
    db_register_functions(db);
    db_register_modules(db);
    return true;
}

// ---------------------------------------------------------------------------
// Column layout
// ---------------------------------------------------------------------------
static const char *const NO_PAD_NAMES[] = {
    "c", "s", "id", "ip", "op", "rc", "pid", "c_ip", "log_line", "log_level",
    "log_mark", "log_pid", "log_pri", "log_msgid", nullptr
};

static bool no_pad(const std::string &name)
{
    for (int i = 0; NO_PAD_NAMES[i] != nullptr; i++) {
        if (name == NO_PAD_NAMES[i]) return true;
    }
    return false;
}

static bool looks_numeric(const std::string &s)
{
    if (s.empty()) return false;
    size_t i = 0;
    if (s[i] == '-' || s[i] == '+') i++;
    bool digits = false, dot = false;
    for (; i < s.size(); i++) {
        if (isdigit((unsigned char)s[i])) digits = true;
        else if (s[i] == '.' && !dot) dot = true;
        else return false;
    }
    return digits;
}

std::string render_db_rows(const DbResult &r)
{
    if (r.cols.empty()) return "";
    size_t nc = r.cols.size();
    std::vector<int> width(nc, 0);
    std::vector<bool> numeric(nc, false);
    for (size_t i = 0; i < nc; i++) {
        width[i] = (int)r.cols[i].name.size();
        numeric[i] = false;
    }
    // Determine alignment from the first row's values
    if (!r.rows.empty()) {
        for (size_t i = 0; i < nc; i++) {
            const std::string &v = r.rows[0][i];
            numeric[i] = looks_numeric(v) && !no_pad(r.cols[i].name);
        }
    }
    for (size_t i = 0; i < nc; i++) {
        int w = (int)r.cols[i].name.size();
        for (auto &row : r.rows) {
            int l = utf8_char_count(row[i]);
            if (l > w) w = l;
        }
        if (numeric[i]) {
            if (!no_pad(r.cols[i].name) && w < 10) w = 10;
        }
        width[i] = w;
    }
    std::string out;
    // header
    for (size_t i = 0; i < nc; i++) {
        int w = width[i];
        int pad = (w - utf8_char_count(r.cols[i].name)) / 2;
        if (pad < 0) pad = 0;
        out += std::string(pad, ' ');
        out += r.cols[i].name;
        if ((int)(pad + utf8_char_count(r.cols[i].name)) < w) {
            out += std::string(w - pad - utf8_char_count(r.cols[i].name), ' ');
        }
        out += ' ';
    }
    if (!out.empty()) out += '\n';
    for (auto &row : r.rows) {
        std::string line;
        for (size_t i = 0; i < nc; i++) {
            int w = width[i];
            int l = utf8_char_count(row[i]);
            if (numeric[i]) {
                if (w - l > 0) line += std::string(w - l, ' ');
                line += row[i];
            } else {
                line += row[i];
                if (w - l > 0) line += std::string(w - l, ' ');
            }
            line += ' ';
        }
        out += line;
        out += '\n';
    }
    return out;
}

std::string DbView::render()
{
    return render_db_rows(result);
}

std::string DbView::render_csv()
{
    std::string out;
    for (size_t i = 0; i < result.cols.size(); i++) {
        if (i) out += ',';
        out += result.cols[i].name;
    }
    if (!result.cols.empty()) out += '\n';
    for (auto &row : result.rows) {
        for (size_t i = 0; i < row.size(); i++) {
            if (i) out += ',';
            bool quote = row[i].find_first_of(",\"\n\r") != std::string::npos;
            if (quote) {
                out += '"';
                for (char c : row[i]) {
                    if (c == '"') out += "\"\"";
                    else out += c;
                }
                out += '"';
            } else {
                out += row[i];
            }
        }
        out += '\n';
    }
    return out;
}

static std::string json_escape(const std::string &s)
{
    std::string out;
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            default:
                if (c < 0x20) out += fmt_str("\\u%04x", c);
                else out += (char)c;
        }
    }
    return out;
}

std::string DbView::render_json()
{
    std::string out = "[\n";
    for (size_t r = 0; r < result.rows.size(); r++) {
        out += "    {\n";
        for (size_t i = 0; i < result.cols.size(); i++) {
            out += "        \"" + json_escape(result.cols[i].name) + "\": ";
            const std::string &v = result.rows[r][i];
            int t = result.types[r][i];
            if (t == 3) out += "null";
            else if (t == 1 || t == 2) out += v;
            else out += "\"" + json_escape(v) + "\"";
            if (i + 1 < result.cols.size()) out += ',';
            out += '\n';
        }
        out += "    }";
        if (r + 1 < result.rows.size()) out += ',';
        out += '\n';
    }
    out += "]\n";
    return out;
}

std::string DbView::render_jsonlines()
{
    std::string out;
    for (size_t r = 0; r < result.rows.size(); r++) {
        out += '{';
        for (size_t i = 0; i < result.cols.size(); i++) {
            if (i) out += ',';
            out += "\"" + json_escape(result.cols[i].name) + "\":";
            const std::string &v = result.rows[r][i];
            int t = result.types[r][i];
            if (t == 3) out += "null";
            else if (t == 1 || t == 2) out += v;
            else out += "\"" + json_escape(v) + "\"";
        }
        out += "}\n";
    }
    return out;
}

static const char *const BOX_TL = "\u250f";
static const char *const BOX_TR = "\u2513";
static const char *const BOX_BL = "\u2517";
static const char *const BOX_BR = "\u251b";
static const char *const BOX_H = "\u2501";
static const char *const BOX_V = "\u2503";
static const char *const BOX_TD = "\u252b";
static const char *const BOX_BU = "\u253b";
static const char *const BOX_VL = "\u2523";
static const char *const BOX_VR = "\u252b";

std::string DbView::render_table()
{
    if (result.cols.empty()) return "";
    size_t nc = result.cols.size();
    std::vector<int> width(nc, 0);
    std::vector<bool> numeric(nc, false);
    for (size_t i = 0; i < nc; i++) {
        width[i] = (int)utf8_char_count(result.cols[i].name);
    }
    if (!result.rows.empty()) {
        for (size_t i = 0; i < nc; i++) {
            numeric[i] = looks_numeric(result.rows[0][i]) &&
                         !no_pad(result.cols[i].name);
        }
    }
    for (size_t i = 0; i < nc; i++) {
        int w = (int)utf8_char_count(result.cols[i].name);
        for (auto &row : result.rows) {
            int l = utf8_char_count(row[i]);
            if (l > w) w = l;
        }
        if (numeric[i]) {
            if (!no_pad(result.cols[i].name) && w < 10) w = 10;
        }
        width[i] = w;
    }
    std::string out;
    out += BOX_TL;
    for (size_t i = 0; i < nc; i++) {
        if (i) out += BOX_TD;
        out += std::string(width[i] + 2, *BOX_H);
    }
    out += BOX_TR;
    out += '\n';
    out += BOX_V;
    for (size_t i = 0; i < nc; i++) {
        if (i) out += BOX_V;
        int w = width[i] + 2;
        int l = utf8_char_count(result.cols[i].name);
        int pad = (w - l) / 2;
        std::string cell = "\033[1m" + std::string(pad, ' ') + result.cols[i].name +
                           std::string(w - pad - l, ' ') + "\033[0m";
        out += cell;
    }
    out += BOX_V;
    out += '\n';
    // separator
    out += BOX_VL;
    for (size_t i = 0; i < nc; i++) {
        if (i) out += BOX_BU;
        out += std::string(width[i] + 2, '\u2500');
    }
    out += BOX_VR;
    out += '\n';
    for (auto &row : result.rows) {
        out += BOX_V;
        for (size_t i = 0; i < nc; i++) {
            if (i) out += BOX_V;
            int w = width[i] + 2;
            int l = utf8_char_count(row[i]);
            if (numeric[i]) {
                out += std::string(w - l, ' ') + row[i];
            } else {
                out += row[i] + std::string(w - l, ' ');
            }
        }
        out += BOX_V;
        out += '\n';
    }
    out += BOX_BL;
    for (size_t i = 0; i < nc; i++) {
        if (i) out += BOX_VL;
        out += std::string(width[i] + 2, '\u2500');
    }
    out += BOX_BR;
    out += '\n';
    return out;
}

std::string DbView::schema_text()
{
    std::string out;
    out += "ATTACH DATABASE '' AS 'main';\n";
    out += "ATTACH DATABASE '' AS 'lnav_db';\n";
    return out;
}

// ---------------------------------------------------------------------------
// Fuzzy matching
// ---------------------------------------------------------------------------
static int fuzzy_match_impl(const std::string &pattern, const std::string &str)
{
    size_t pi = 0;
    std::vector<int> idx;
    for (size_t i = 0; i < str.size() && pi < pattern.size(); i++) {
        if (str[i] == pattern[pi]) {
            idx.push_back((int)i);
            pi++;
        }
    }
    if (pi < pattern.size()) return -1;
    int m = (int)pattern.size();
    int n = (int)str.size();
    int internal = 0;
    for (size_t i = 1; i < idx.size(); i++) {
        if (idx[i] != idx[i - 1] + 1) internal++;
    }
    int lead = idx.empty() ? 0 : idx[0];
    int lead_pen = 0;
    if (lead > 0) {
        lead_pen = 15 + 5 * lead;
        if (lead_pen > 30) lead_pen = 30;
    }
    return 100 + 16 * m - n - 15 * internal - lead_pen;
}

int fuzzy_match_score(const std::string &needle, const std::string &haystack)
{
    int sc = fuzzy_match_impl(needle, haystack);
    return sc;
}

std::vector<std::string> did_you_mean(const std::string &word,
                                      const std::vector<std::string> &options,
                                      int limit)
{
    std::vector<std::pair<int, std::string>> scored;
    for (auto &opt : options) {
        int sc = fuzzy_match_impl(word, opt);
        if (sc >= 90) scored.push_back({sc, opt});
    }
    std::sort(scored.begin(), scored.end(),
              [](const std::pair<int, std::string> &a, const std::pair<int, std::string> &b) {
