static const char *const BASE_COLS[] = {
    "log_part", "log_idle_msecs", "log_mark", "log_comment", "log_tags",
    "log_annotations", "log_filters", nullptr
};

static std::string base_col_value(const std::shared_ptr<LogFile> &f, int mi, const char *name)
{
    if (f == nullptr || mi >= (int)f->messages.size()) return "";
    const LogMessage &msg = f->messages[mi];
    if (strcmp(name, "log_part") == 0) return "";
    if (strcmp(name, "log_idle_msecs") == 0) {
        if (mi == 0 || !msg.has_time) return "0";
        usecs_t prev = f->messages[mi - 1].time;
        long long d = (long long)((msg.time - prev) / 1000);
        if (d < 0) d = 0;
        return std::to_string(d);
    }
    if (strcmp(name, "log_mark") == 0) return "0";
    return "";
}

static void fill_row(VTabSpec *spec, int fi, int mi, std::vector<std::string> &out)
{
    out.clear();
    const std::shared_ptr<LogFile> &f = (*spec->files)[fi];
    if (f == nullptr) {
        out.resize(spec->cols.size(), "");
        return;
    }
    if (mi >= (int)f->messages.size()) {
        out.resize(spec->cols.size(), "");
        return;
    }
    const LogMessage &msg = f->messages[mi];
    for (auto &c : spec->cols) {
        if (c == "log_line") {
            out.push_back(std::to_string(msg.line_number));
        } else if (c == "log_time") {
            out.push_back(msg.has_time ? format_time_iso(msg.time) : "");
        } else if (c == "log_level") {
            out.push_back(msg.level);
        } else if (c == "log_text") {
            std::string text;
            for (int i = 0; i < msg.num_lines; i++) {
                int ln = msg.line_number + i;
                if (ln >= 0 && ln < (int)f->lines.size()) {
                    if (i) text += "\n";
                    text += f->lines[ln];
                }
            }
            out.push_back(text);
        } else if (c.compare(0, 4, "log_") == 0) {
            out.push_back(base_col_value(f, mi, c.c_str()));
        } else {
            auto iter = msg.fields.find(c);
            out.push_back(iter == msg.fields.end() ? "" : iter->second);
        }
    }
}

}  // namespace lnav
