// ---------------------------------------------------------------------------
// sqlite virtual table
// ---------------------------------------------------------------------------
struct LogVTab {
    sqlite3_vtab base;
    VTabSpec *spec;
};

struct LogVCursor {
    sqlite3_vtab_cursor base;
    int fi = 0;
    int mi = 0;
    bool eof = true;
    std::vector<std::string> row;
};

static int vtConnect(sqlite3 *db, void *aux, int argc, const char **argv,
                     sqlite3_vtab **ppVtab, char **pzErr)
{
    (void)db; (void)argc; (void)argv; (void)pzErr;
    auto *spec = (VTabSpec *)aux;
    auto *vt = new LogVTab();
    memset(&vt->base, 0, sizeof(vt->base));
    vt->spec = spec;
    std::string schema = "CREATE TABLE x(";
    for (size_t i = 0; i < spec->cols.size(); i++) {
        if (i) schema += ",";
        schema += spec->cols[i];
        if (spec->cols[i] == "log_line") schema += " INTEGER PRIMARY KEY";
    }
    if (spec->text_col) schema += ",log_text TEXT HIDDEN";
    schema += ");";
    int rc = sqlite3_declare_vtab(db, schema.c_str());
    if (rc != SQLITE_OK) {
        delete vt;
        return rc;
    }
    *ppVtab = &vt->base;
    return SQLITE_OK;
}

static int vtDisconnect(sqlite3_vtab *vt)
{
    delete (LogVTab *)vt;
    return SQLITE_OK;
}

static int vtBestIndex(sqlite3_vtab *vt, sqlite3_index_info *info)
{
    (void)vt;
    int line_idx = -1;
    for (int i = 0; i < info->nConstraint; i++) {
        const auto &c = info->aConstraint[i];
        if (c.usable && c.iColumn >= 0) {
            std::string col = ((LogVTab *)vt)->spec->cols[c.iColumn];
            if (col == "log_line" && c.op == SQLITE_INDEX_CONSTRAINT_EQ) {
                line_idx = i;
            }
        }
    }
    if (line_idx >= 0) {
        info->aConstraintUsage[line_idx].argvIndex = 1;
        info->aConstraintUsage[line_idx].omit = 1;
        info->estimatedCost = 1.0;
        info->estimatedRows = 1;
    } else {
        info->estimatedCost = 10000.0;
        info->estimatedRows = 10000;
    }
    return SQLITE_OK;
}

static int vtOpen(sqlite3_vtab *vt, sqlite3_vtab_cursor **cur)
{
    (void)vt;
    auto *c = new LogVCursor();
    c->base.pVtab = vt;
    *cur = &c->base;
    return SQLITE_OK;
}

static int vtClose(sqlite3_vtab_cursor *cur)
{
    delete (LogVCursor *)cur;
    return SQLITE_OK;
}

static int total_rows(VTabSpec *spec)
{
    int total = 0;
    if (spec->focused_only) {
        return (spec->focused_msg >= 0) ? 1 : 0;
    }
    if (spec->files == nullptr) return 0;
    for (auto &f : *spec->files) {
        if (f == nullptr) continue;
        total += (int)f->messages.size();
    }
    return total;
}

static void row_at(VTabSpec *spec, int n, int &fi, int &mi)
{
    if (spec->focused_only) {
        fi = spec->focused_file;
        mi = spec->focused_msg;
        return;
    }
    int idx = 0;
    for (size_t i = 0; i < spec->files->size(); i++) {
        auto &f = (*spec->files)[i];
        if (f == nullptr) continue;
        int c = (int)f->messages.size();
        if (n < idx + c) {
            fi = (int)i;
            mi = n - idx;
            return;
        }
        idx += c;
    }
    fi = (int)spec->files->size();
    mi = 0;
}

static int vtFilter(sqlite3_vtab_cursor *cur, int idxNum, const char *idxStr,
                    int argc, sqlite3_value **argv)
{
    auto *c = (LogVCursor *)cur;
    auto *spec = ((LogVTab *)cur->pVtab)->spec;
    (void)idxStr;
    c->fi = 0;
    c->mi = 0;
    if (idxNum == 1 && argc >= 1) {
        long long want = sqlite3_value_int64(argv[0]);
        int total = total_rows(spec);
        // find the row whose log_line matches
        int found = -1;
        for (int n = 0; n < total; n++) {
            int fi, mi;
            row_at(spec, n, fi, mi);
            if (spec->files == nullptr) break;
            if (fi >= (int)spec->files->size()) break;
            auto &f = (*spec->files)[fi];
            if (f == nullptr || mi >= (int)f->messages.size()) continue;
            if (f->messages[mi].line_number == want) {
                found = n;
                break;
            }
        }
        if (found < 0) {
            c->eof = true;
            return SQLITE_OK;
        }
        row_at(spec, found, c->fi, c->mi);
    } else {
        c->fi = 0;
        c->mi = 0;
    }
    c->eof = total_rows(spec) <= 0;
    if (!c->eof && idxNum != 1) {
        int total = total_rows(spec);
        if (total <= 0) c->eof = true;
        else row_at(spec, 0, c->fi, c->mi);
    }
    if (!c->eof) {
        vtab_fill_row(spec, c->fi, c->mi, c->row);
        if (c->row.empty()) c->eof = true;
    }
    return SQLITE_OK;
}

static int vtNext(sqlite3_vtab_cursor *cur)
{
    auto *c = (LogVCursor *)cur;
    auto *spec = ((LogVTab *)cur->pVtab)->spec;
    int total = total_rows(spec);
    int n = 0;
    // compute current row number
    if (spec->focused_only) {
        n = 0;
    } else {
        int idx = 0;
        for (size_t i = 0; i < spec->files->size(); i++) {
            auto &f = (*spec->files)[i];
            if (f == nullptr) continue;
            if ((int)i == c->fi) { n = idx + c->mi; break; }
            idx += (int)f->messages.size();
        }
    }
    n++;
    if (n >= total) {
        c->eof = true;
    } else {
        row_at(spec, n, c->fi, c->mi);
        vtab_fill_row(spec, c->fi, c->mi, c->row);
    }
    return SQLITE_OK;
}

static int vtEof(sqlite3_vtab_cursor *cur)
{
    return ((LogVCursor *)cur)->eof ? 1 : 0;
}

static int vtColumn(sqlite3_vtab_cursor *cur, sqlite3_context *ctx, int i)
{
    auto *c = (LogVCursor *)cur;
    auto *spec = ((LogVTab *)cur->pVtab)->spec;
    if (i >= (int)c->row.size()) {
        sqlite3_result_null(ctx);
        return SQLITE_OK;
    }
    const std::string &v = c->row[i];
    if (v.empty()) {
        sqlite3_result_null(ctx);
        return SQLITE_OK;
    }
    sqlite3_result_text(ctx, v.c_str(), (int)v.size(), SQLITE_TRANSIENT);
    return SQLITE_OK;
}

static int vtRowid(sqlite3_vtab_cursor *cur, sqlite3_int64 *rowid)
{
    auto *c = (LogVCursor *)cur;
    *rowid = (sqlite3_int64)c->fi * 1000000 + c->mi;
    return SQLITE_OK;
}

static sqlite3_module g_log_module = {
    0, nullptr, nullptr, vtConnect, vtConnect, nullptr, nullptr, nullptr, nullptr,
    vtBestIndex, vtDisconnect, vtOpen, vtClose, vtFilter, vtNext, vtEof, vtColumn,
    vtRowid, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
    nullptr, nullptr, nullptr
};

void db_register_modules(sqlite3 *db)
{
    sqlite3_create_module(db, "logvtab_impl", &g_log_module, nullptr);
}

// ---------------------------------------------------------------------------
// Custom SQL functions
// ---------------------------------------------------------------------------
static void fn_fuzzy_match(sqlite3_context *ctx, int argc, sqlite3_value **argv)
{
    if (argc < 2) {
        sqlite3_result_null(ctx);
        return;
    }
    const unsigned char *p = sqlite3_value_text(argv[0]);
    const unsigned char *s = sqlite3_value_text(argv[1]);
    if (p == nullptr || s == nullptr) {
        sqlite3_result_null(ctx);
        return;
    }
    int sc = fuzzy_match_score((const char *)p, (const char *)s);
    if (sc < 0) {
        sqlite3_result_null(ctx);
    } else {
        sqlite3_result_int(ctx, sc);
    }
}

static void fn_version(sqlite3_context *ctx, int argc, sqlite3_value **argv)
{
    (void)argc; (void)argv;
    sqlite3_result_text(ctx, LNAV_VERSION, -1, SQLITE_TRANSIENT);
}

static void fn_log_msg_line(sqlite3_context *ctx, int argc, sqlite3_value **argv)
{
    (void)argc; (void)argv;
    sqlite3_result_int64(ctx, g_focused_line_number);
}

void db_register_functions(sqlite3 *db)
{
    sqlite3_create_function(db, "fuzzy_match", 2, SQLITE_UTF8, 0, fn_fuzzy_match, nullptr, nullptr);
    sqlite3_create_function(db, "lnav_version", 0, SQLITE_UTF8, 0, fn_version, nullptr, nullptr);
    sqlite3_create_function(db, "log_msg_line", 0, SQLITE_UTF8, 0, fn_log_msg_line, nullptr, nullptr);
}

}  // namespace lnav
