#include "lnav.hh"
#include "help.hh"
#include "paths.hh"
#include "logfile.hh"
#include "db.hh"
#include "commands.hh"
#include "mgmt.hh"
#include "util.hh"
#include <unistd.h>
#include <glob.h>
#include <dirent.h>
#include <sys/stat.h>
#include <fcntl.h>

namespace lnav {

const char *LNAV_VERSION = "0.14.0-8ad2d43";
const char *g_prog_name = "lnav";

Session g_session;
std::vector<std::shared_ptr<LogFile>> g_files;
std::vector<std::string> g_args_files;
std::vector<std::string> g_text_files;

static void load_error(const std::string &path, const std::string &reason)
{
    DisplayError e;
    e.error = "unable to open file: " + path;
    e.reason = reason;
    report_error(e);
}

static void collect_files(const std::string &path, bool recurse,
                          std::vector<std::string> &out)
{
    struct stat st;
    if (stat(path.c_str(), &st) < 0) {
        // Try a glob
        glob_t g;
        memset(&g, 0, sizeof(g));
        if (glob(path.c_str(), 0, nullptr, &g) == 0 && g.gl_pathc > 0) {
            for (size_t i = 0; i < g.gl_pathc; i++) {
                collect_files(g.gl_pathv[i], recurse, out);
            }
            globfree(&g);
            return;
        }
        globfree(&g);
        out.push_back(path);
        return;
    }
    if (S_ISDIR(st.st_mode)) {
        DIR *d = opendir(path.c_str());
        if (d == nullptr) return;
        std::vector<std::string> entries;
        struct dirent *de;
        while ((de = readdir(d)) != nullptr) {
            std::string n = de->d_name;
            if (n == "." || n == "..") continue;
            entries.push_back(n);
        }
        closedir(d);
        std::sort(entries.begin(), entries.end());
        for (auto &e : entries) {
            std::string full = path == "/" ? "/" + e : path + "/" + e;
            struct stat st2;
            if (stat(full.c_str(), &st2) < 0) continue;
            if (S_ISDIR(st2.st_mode)) {
                if (recurse) collect_files(full, recurse, out);
            } else {
                out.push_back(full);
            }
        }
        return;
    }
    out.push_back(path);
}

static std::string default_syslog_file()
{
    static const char *const cands[] = {
        "/var/log/syslog", "/var/log/messages", "/var/log/system.log",
        "/var/log/dpkg.log", nullptr
    };
    for (int i = 0; cands[i] != nullptr; i++) {
        struct stat st;
        if (stat(cands[i], &st) == 0 && S_ISREG(st.st_mode)) return cands[i];
    }
    return "";
}

static bool load_all(const Options &opts)
{
    std::vector<std::string> paths;
    if (g_args_files.empty()) {
        if (opts.no_default_syslog) return true;
        std::string ds = default_syslog_file();
        if (ds.empty()) {
            DisplayError e;
            e.error = "nothing to do";
            e.reason = "no files given or default files found";
            e.help_raw.push_back(" = help: use the \xe2\x80\x9c-N\xe2\x80\x9d option to open lnav without loading any files");
            report_error(e);
            return false;
        }
        paths.push_back(ds);
    } else {
        for (auto &p : g_args_files) {
            collect_files(p, opts.recurse, paths);
        }
    }
    bool had_error = false;
    for (auto &p : paths) {
        bool ok = false;
        auto lf = load_file(p, ok);
        if (!ok) {
            load_error(p, "No such file or directory");
            had_error = true;
            continue;
        }
        g_files.push_back(lf);
        if (lf->is_text) {
            g_text_files.push_back(p);
            g_session.current_view_is_text = g_files.size() == 1;
        }
    }
    if (had_error) {
        g_session.error_seen = true;
        return false;
    }
    // Sort the log files by path so that ties are deterministic
    std::sort(g_files.begin(), g_files.end(),
              [](const std::shared_ptr<LogFile> &a, const std::shared_ptr<LogFile> &b) {
                  return a->path < b->path;
              });
    return true;
}

static void setup_db(DbView &db)
{
    if (!db.open()) return;
    db_set_files(db, g_files, g_session);
}

int main(int argc, char **argv)
{
    g_prog_name = argc > 0 && argv[0] != nullptr ? argv[0] : "lnav";
    Options opts;
    int rc = parse_args(argc, argv, opts);
    if (rc != 0) return rc;

    if (opts.mgmt) {
        return mgmt_main(argc, argv, opts);
    }

    if (opts.version) {
        print_version();
        return 0;
    }
    if (opts.help) {
        print_help(opts);
        return 0;
    }

    init_help();

    if (!load_all(opts)) {
        if (!opts.headless && !isatty(1)) {
            print_tty_error();
        }
        return g_exit_code;
    }

    if (!opts.headless && !isatty(1)) {
        print_tty_error();
        return 1;
    }

    DbView db;
    setup_db(db);

    // Execute the commands
    for (auto &c : opts.commands) {
        if (g_session.quit) break;
        g_session.command_index++;
        std::string loc = "command-option:" + std::to_string(g_session.command_index);
        if (c.empty()) continue;
        if (c[0] == ':') {
            run_command(c.substr(1), loc);
        } else if (c[0] == ';') {
            run_sql(c.substr(1), loc, db);
        } else if (c[0] == '|') {
            run_script(c.substr(1), loc, db, opts);
        } else {
            DisplayError e;
            e.error = "invalid value for \xe2\x80\x9c-c\xe2\x80\x9d option";
            e.reason = "command type prefix is missing";
            e.location = "command-line argument";
            e.context.push_back("  -c " + c);
            e.help_raw.push_back(" = help: command arguments must start with one of the following symbols to denote the type of command:");
            e.help_raw.push_back("            : - an lnav command   (e.g. :goto 42)");
            e.help_raw.push_back("            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)");
            e.help_raw.push_back("            | - an lnav script    (e.g. |rename-stdin foo)");
            report_error(e);
            g_session.error_seen = true;
        }
    }

    if (g_session.error_seen) return 0;

    if (opts.headless) {
        print_final_output();
    }

    return 0;
}

}  // namespace lnav

int main(int argc, char **argv);

int main(int argc, char **argv)
{
    return lnav::main(argc, argv);
}
