    std::string list;
    for (size_t i = 0; i < args.size(); i++) {
        if (i) list += " ";
        list += args[i];
    }
    arg_error(std::string(args.size() == 1 ? "The following argument was not expected: "
                                          : "The following arguments were not expected: ") + list,
              E_ARGS);
}

int parse_args(int argc, char **argv, Options &opts)
{
    std::vector<std::string> unexpected_args;
    bool first = true;
    for (int i = 1; i < argc; i++) {
        std::string a = argv[i];
        if (a == "--") {
            for (int j = i + 1; j < argc; j++) g_args_files.push_back(argv[j]);
            break;
        }
        if (a.size() > 1 && a[0] == '-' && !isdigit((unsigned char)a[1])) {
            std::string name = a;
            std::string value;
            bool have_value = false;
            size_t eq = a.find('=');
            if (a[1] == '-') {
                if (eq != std::string::npos) {
                    name = a.substr(0, eq);
                    value = a.substr(eq + 1);
                    have_value = true;
                }
            }
            first = false;
            if (name == "-h" || name == "--help") {
                opts.help = true;
            } else if (name == "-H") {
                opts.internal_help = true;
            } else if (name == "-V" || name == "--version") {
                opts.version = true;
            } else if (name == "-n") {
                opts.headless = true;
            } else if (name == "-N") {
                opts.no_default_syslog = true;
            } else if (name == "-q") {
                opts.quiet = true;
            } else if (name == "-W") {
                opts.warnings = true;
            } else if (name == "-u") {
                opts.update_formats = true;
            } else if (name == "-r") {
                opts.recurse = true;
            } else if (name == "-R") {
                opts.rotated = true;
            } else if (name == "-t") {
                opts.stdin_is_log = true;
            } else if (name == "-i") {
                opts.install = true;
            } else if (name == "-m") {
                opts.mgmt = true;
            } else if (name == "-C") {
                opts.check = true;
            } else if (name == "-d") {
                if (i + 1 >= argc) {
                    arg_error("-d: 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                }
                opts.debug_file = argv[++i];
                opts.debug = true;
            } else if (name == "-I") {
                if (i + 1 >= argc) {
                    arg_error("-I: 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                }
                std::string dir = argv[++i];
                if (!dir_exists(dir)) {
                    arg_error("-I: Directory does not exist: " + dir, 105);
                    return g_exit_code;
                }
                opts.include_dirs.push_back(dir);
            } else if (name == "-c") {
                if (i + 1 >= argc) {
                    arg_error("-c: 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                }
                opts.commands.push_back(argv[++i]);
            } else if (name == "-e") {
                if (i + 1 >= argc) {
                    arg_error("-e: 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                }
                opts.commands.push_back("|exec:" + std::string(argv[++i]));
            } else if (name == "-f") {
                if (i + 1 >= argc) {
                    arg_error("-f: 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                }
                opts.commands.push_back("|" + std::string(argv[++i]));
            } else if (name == "-S" || name == "--since") {
                if (have_value) opts.since = value;
                else if (i + 1 >= argc) {
                    arg_error(name + ": 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                } else opts.since = argv[++i];
            } else if (name == "-U" || name == "--until") {
                if (have_value) opts.until = value;
                else if (i + 1 >= argc) {
                    arg_error(name + ": 1 required  missing", E_MISSING_OPT_ARG);
                    return g_exit_code;
                } else opts.until = argv[++i];
            } else {
                unexpected_args.push_back(a);
                unexpected(unexpected_args);
                return g_exit_code;
            }
        } else {
            if (opts.mgmt) {
                // Positional arguments in management mode are handled there
                unexpected_args.push_back(a);
                continue;
            }
            g_args_files.push_back(a);
        }
    }
    if (!unexpected_args.empty()) {
        unexpected(unexpected_args);
        return g_exit_code;
    }
    return 0;
}

