struct ViewLine {
    int file_index;
    int msg_index;
    int line_offset;
    usecs_t time;
    std::string text;
    std::string level;
    bool has_time;
    bool marked;
};

static std::vector<ViewLine> g_view;
static std::vector<std::pair<std::string, std::string>> g_filters;  // type,pattern
static std::vector<bool> g_filter_enabled;
static int g_min_level = -1;
static std::vector<bool> g_marks;
static std::string g_redirect_path;
static bool g_redirect_active = false;
static std::string g_redirect_data;
