static int level_index(const std::string &lv)
{
    static const char *const levels[] = {
        "trace", "debug", "info", "notice", "warning", "error", "critical", "fatal",
        nullptr
    };
    for (int i = 0; levels[i] != nullptr; i++) {
        if (lv == levels[i]) return i;
    }
    return -1;
}

static void rebuild_view()
{
    g_view.clear();
    struct Item {
        usecs_t time;
        int file_index;
        int line_number;
        int msg_index;
        int line_offset;
        std::string text;
        std::string level;
        bool has_time;
    };
    std::vector<Item> items;
    for (size_t fi = 0; fi < g_files.size(); fi++) {
        auto &f = g_files[fi];
        if (f == nullptr || f->is_text) continue;
        for (size_t mi = 0; mi < f->messages.size(); mi++) {
            const LogMessage &msg = f->messages[mi];
            for (int j = 0; j < msg.num_lines; j++) {
                int ln = msg.line_number + j;
                if (ln < 0 || ln >= (int)f->lines.size()) continue;
                Item it;
                it.time = msg.time;
                it.file_index = (int)fi;
                it.line_number = ln;
                it.msg_index = (int)mi;
                it.line_offset = j;
                it.text = f->lines[ln];
                it.level = msg.level;
                it.has_time = msg.has_time;
                items.push_back(it);
            }
        }
    }
    std::sort(items.begin(), items.end(), [](const Item &a, const Item &b) {
        if (a.time != b.time) return a.time < b.time;
        if (a.file_index != b.file_index) return a.file_index < b.file_index;
        if (a.line_number != b.line_number) return a.line_number < b.line_number;
        return a.line_offset < b.line_offset;
    });
    for (auto &it : items) {
        ViewLine vl;
        vl.file_index = it.file_index;
        vl.msg_index = it.msg_index;
        vl.line_offset = it.line_offset;
        vl.time = it.time;
        vl.text = it.text;
        vl.level = it.level;
        vl.has_time = it.has_time;
        vl.marked = false;
        g_view.push_back(vl);
    }
    g_marks.assign(g_view.size(), false);
}

static bool filter_matches(const std::pair<std::string, std::string> &f,
                           const std::string &text)
{
    try {
        std::regex re(f.second, std::regex::extended);
        return std::regex_search(text, re);
    } catch (...) {
        return text.find(f.second) != std::string::npos;
    }
}

static std::vector<size_t> visible_lines()
{
    std::vector<size_t> out;
    for (size_t i = 0; i < g_view.size(); i++) {
        const ViewLine &vl = g_view[i];
        if (g_session.hide_unmarked && !g_marks[i]) continue;
        if (!g_session.filtering_enabled) {
            out.push_back(i);
            continue;
        }
        bool include = true;
        for (size_t k = 0; k < g_filters.size(); k++) {
            if (!g_filter_enabled[k]) continue;
            bool m = filter_matches(g_filters[k], vl.text);
            if (g_filters[k].first == "in" && !m) include = false;
            if (g_filters[k].first == "out" && m) include = false;
        }
        if (!include) continue;
        if (g_min_level >= 0) {
            int li = level_index(vl.level);
            if (li < 0) li = 8;   // unknown/invalid are always shown
            if (li < g_min_level) continue;
        }
        out.push_back(i);
    }
    return out;
}

