static std::string read_file(const std::string &path)
{
    FILE *fp = path == "-" ? stdin : fopen(path.c_str(), "rb");
    if (fp == nullptr) return "";
    std::string out;
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) out.append(buf, n);
    if (path != "-") fclose(fp);
    return out;
}

static void write_file(const std::string &path, const std::string &data, bool append)
{
    FILE *fp;
    if (path == "-") {
        fp = stdout;
    } else {
        fp = fopen(path.c_str(), append ? "ab" : "wb");
    }
    if (fp == nullptr) return;
    fwrite(data.data(), 1, data.size(), fp);
    if (fp != stdout) fclose(fp);
    else fflush(stdout);
}

static const CmdDoc *doc_for(const std::string &name)
{
    return find_doc(name);
}

static void unknown_command(const std::string &name, const std::string &loc)
{
    DisplayError e;
    e.error = "unknown command: \xe2\x80\x9c" + name + "\xe2\x80\x9d";
    e.location = loc;
    e.context.push_back(":" + name);
    std::vector<std::string> names;
    for (auto &kv : command_docs()) names.push_back(kv.first);
    auto sugg = did_you_mean(name, names, 8);
    if (!sugg.empty()) {
        e.note_header = "note: did you mean one of the following:";
        for (auto &s : sugg) {
            const CmdDoc *d = find_doc(s);
            std::string desc;
            if (d != nullptr && !d->desc.empty()) {
                desc = d->desc[0];
                while (desc.size() > 0 && desc[0] == ' ') desc.erase(desc.begin());
                while (desc.size() > 0 && desc[desc.size() - 1] == ' ') desc.pop_back();
            }
            e.note_items.push_back({s, desc});
        }
    }
    report_error(e);
    g_session.error_seen = true;
}

static void cmd_error(const std::string &msg, const std::string &reason,
                      const std::string &name, const std::string &args,
                      const std::string &loc)
{
    DisplayError e;
    e.error = msg;
    e.location = loc;
    e.context.push_back(":" + name + (args.empty() ? "" : " " + args));
    const CmdDoc *d = doc_for(name);
    if (d != nullptr) {
        e.help_synopsis = d->synopsis;
        e.help_desc = d->desc;
    }
    if (!reason.empty()) e.reason = reason;
    report_error(e);
    g_session.error_seen = true;
}

static void cmd_error_noargs(const std::string &msg, const std::string &name,
                             const std::string &loc)
