#include "commands.hh"
#include "help.hh"
#include "db.hh"
#include "util.hh"
#include "logfile.hh"
#include <unistd.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <glob.h>

namespace lnav {

DbView *g_db = nullptr;

// ---------------------------------------------------------------------------
// Log view construction
// ---------------------------------------------------------------------------
struct ViewLine {
    int file_index;
    int msg_index;
    int line_offset;
    usecs_t time;
    std::string text;
    std::string level;
    bool has_time;
    bool marked;
};

static std::vector<ViewLine> g_view;
static std::vector<std::pair<std::string, std::string>> g_filters;  // type,pattern
static std::vector<bool> g_filter_enabled;
static int g_min_level = -1;
static std::vector<bool> g_marks;
static std::string g_redirect_path;
static bool g_redirect_active = false;
static std::string g_redirect_data;
static std::vector<int> g_marked_lines;

static int level_index(const std::string &lv)
{
    static const char *const levels[] = {
        "trace", "debug", "info", "notice", "warning", "error", "critical", "fatal",
        nullptr
    };
    for (int i = 0; levels[i] != nullptr; i++) {
        if (lv == levels[i]) return i;
    }
    return -1;
}

static void rebuild_view()
{
    g_view.clear();
    struct Item {
        usecs_t time;
        int file_index;
        int line_number;
        int msg_index;
        int line_offset;
        std::string text;
        std::string level;
        bool has_time;
    };
    std::vector<Item> items;
    for (size_t fi = 0; fi < g_files.size(); fi++) {
        auto &f = g_files[fi];
        if (f == nullptr || f->is_text) continue;
        for (size_t mi = 0; mi < f->messages.size(); mi++) {
            const LogMessage &msg = f->messages[mi];
            for (int j = 0; j < msg.num_lines; j++) {
                int ln = msg.line_number + j;
                if (ln < 0 || ln >= (int)f->lines.size()) continue;
                Item it;
                it.time = msg.time;
                it.file_index = (int)fi;
                it.line_number = ln;
                it.msg_index = (int)mi;
                it.line_offset = j;
                it.text = f->lines[ln];
                it.level = msg.level;
                it.has_time = msg.has_time;
                items.push_back(it);
            }
        }
    }
    std::sort(items.begin(), items.end(), [](const Item &a, const Item &b) {
        if (a.time != b.time) return a.time < b.time;
        if (a.file_index != b.file_index) return a.file_index < b.file_index;
        if (a.line_number != b.line_number) return a.line_number < b.line_number;
        return a.line_offset < b.line_offset;
    });
    for (auto &it : items) {
        ViewLine vl;
        vl.file_index = it.file_index;
        vl.msg_index = it.msg_index;
        vl.line_offset = it.line_offset;
        vl.time = it.time;
        vl.text = it.text;
        vl.level = it.level;
        vl.has_time = it.has_time;
        vl.marked = false;
        g_view.push_back(vl);
    }
    g_marks.assign(g_view.size(), false);
}

static bool filter_matches(const std::pair<std::string, std::string> &f,
                           const std::string &text)
{
    try {
        std::regex re(f.second, std::regex::extended);
        return std::regex_search(text, re);
    } catch (...) {
        return text.find(f.second) != std::string::npos;
    }
}

static std::vector<size_t> visible_lines()
{
    std::vector<size_t> out;
    for (size_t i = 0; i < g_view.size(); i++) {
        const ViewLine &vl = g_view[i];
        if (g_session.hide_unmarked && !g_marks[i]) continue;
        if (!g_session.filtering_enabled) {
            out.push_back(i);
            continue;
        }
        bool include = true;
        for (size_t k = 0; k < g_filters.size(); k++) {
            if (!g_filter_enabled[k]) continue;
            bool m = filter_matches(g_filters[k], vl.text);
            if (g_filters[k].first == "in" && !m) include = false;
            if (g_filters[k].first == "out" && m) include = false;
        }
        if (!include) continue;
        if (g_min_level >= 0) {
            int li = level_index(vl.level);
            if (li < 0) li = 8;   // unknown/invalid are always shown
            if (li < g_min_level) continue;
        }
        out.push_back(i);
    }
    return out;
}

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------
static std::string read_file(const std::string &path)
{
    FILE *fp = path == "-" ? stdin : fopen(path.c_str(), "rb");
    if (fp == nullptr) return "";
    std::string out;
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) out.append(buf, n);
    if (path != "-") fclose(fp);
    return out;
}

static void write_file(const std::string &path, const std::string &data, bool append)
{
    FILE *fp;
    if (path == "-") {
        fp = stdout;
    } else {
        fp = fopen(path.c_str(), append ? "ab" : "wb");
    }
    if (fp == nullptr) return;
    fwrite(data.data(), 1, data.size(), fp);
    if (fp != stdout) fclose(fp);
    else fflush(stdout);
}

static const CmdDoc *doc_for(const std::string &name)
{
    return find_doc(name);
}

static void unknown_command(const std::string &name, const std::string &loc)
{
    DisplayError e;
    e.error = "unknown command: \xe2\x80\x9c" + name + "\xe2\x80\x9d";
    e.location = loc;
    e.context.push_back(":" + name);
    std::vector<std::string> names;
    for (auto &kv : command_docs()) names.push_back(kv.first);
    auto sugg = did_you_mean(name, names, 8);
    if (!sugg.empty()) {
        e.note_header = "note: did you mean one of the following:";
        for (auto &s : sugg) {
            const CmdDoc *d = find_doc(s);
            std::string desc;
            if (d != nullptr && !d->desc.empty()) {
                desc = d->desc[0];
                while (desc.size() > 0 && desc[0] == ' ') desc.erase(desc.begin());
                while (desc.size() > 0 && desc[desc.size() - 1] == ' ') desc.pop_back();
            }
            e.note_items.push_back({s, desc});
        }
    }
    report_error(e);
    g_session.error_seen = true;
}

static void cmd_error(const std::string &msg, const std::string &reason,
                      const std::string &name, const std::string &args,
                      const std::string &loc)
{
    DisplayError e;
    e.error = msg;
    e.location = loc;
    e.context.push_back(":" + name + (args.empty() ? "" : " " + args));
    const CmdDoc *d = doc_for(name);
    if (d != nullptr) {
        e.help_synopsis = d->synopsis;
        e.help_desc = d->desc;
    }
    if (!reason.empty()) e.reason = reason;
    report_error(e);
    g_session.error_seen = true;
}

static void cmd_error_noargs(const std::string &msg, const std::string &name,
                             const std::string &loc)
{
    cmd_error(msg, "", name, "", loc);
}

// ---------------------------------------------------------------------------
// Command implementations
// ---------------------------------------------------------------------------
static void cmd_echo(const std::string &args)
{
    bool no_nl = false;
    std::string msg = args;
    if (starts_with(msg, "-n ")) {
        no_nl = true;
        msg = msg.substr(3);
    } else if (msg == "-n") {
        no_nl = true;
        msg = "";
    }
    g_session.echo_used = true;
    fputs(msg.c_str(), stdout);
    if (!no_nl) fputc('\n', stdout);
    fflush(stdout);
}

static void cmd_filter(const std::string &name, const std::string &args,
                       const std::string &loc)
{
    std::string pat = trim(args);
    if (pat.empty()) {
        cmd_error("expecting a regular expression to filter", "", name, args, loc);
        return;
    }
    if (name == "delete-filter" || name == "disable-filter" || name == "enable-filter") {
        bool found = false;
        for (size_t i = 0; i < g_filters.size(); i++) {
            if (g_filters[i].second == pat) {
                found = true;
                if (name == "delete-filter") {
                    g_filters.erase(g_filters.begin() + i);
                    g_filter_enabled.erase(g_filter_enabled.begin() + i);
                    i--;
                } else {
                    g_filter_enabled[i] = name == "enable-filter";
                }
            }
        }
        if (!found) {
            cmd_error("unable to find filter with value \xe2\x80\x9c" + pat + "\xe2\x80\x9d",
                      "", name, args, loc);
        }
        return;
    }
    if (name == "filter-expr" || name == "clear-filter-expr") {
        return;
    }
    if (name == "toggle-filtering") {
        g_session.filtering_enabled = !g_session.filtering_enabled;
        return;
    }
    std::string type = name == "filter-in" ? "in" : "out";
    for (size_t i = 0; i < g_filters.size(); i++) {
        if (g_filters[i].first == type && g_filters[i].second == pat) {
            g_filter_enabled[i] = true;
            return;
        }
    }
    g_filters.push_back({type, pat});
    g_filter_enabled.push_back(true);
}

static void cmd_write_view(const std::string &args)
{
    std::string path = trim(args);
    std::string data;
    auto vis = visible_lines();
    for (size_t i = 0; i < vis.size(); i++) {
        data += g_view[vis[i]].text;
        data += '\n';
    }
    if (path.empty()) {
        fputs(data.c_str(), stdout);
        fflush(stdout);
        g_session.view_printed = true;
        return;
    }
    write_file(path, data, false);
}

static void cmd_write_to(const std::string &name, const std::string &args,
                         const std::string &loc)
{
    std::string path = trim(args);
    if (g_marked_lines.empty()) {
        cmd_error("no lines marked to write, use 'm' to mark lines", "", name, args, loc);
        return;
    }
    // Collect the raw content of the marked lines, grouped by file
    std::string data;
    for (size_t i = 0; i < g_view.size(); i++) {
        if (!g_marks[i]) continue;
        data += g_view[i].text;
        data += '\n';
    }
    if (path.empty()) {
        fputs(data.c_str(), stdout);
        fflush(stdout);
        g_session.view_printed = true;
        return;
    }
    write_file(path, data, false);
}

static void cmd_mark(const std::string &args, const std::string &loc)
{
    (void)args; (void)loc;
    auto vis = visible_lines();
    if (g_session.top_line >= (int)vis.size()) return;
    size_t idx = vis[g_session.top_line];
    g_marks[idx] = !g_marks[idx];
    if (g_marks[idx]) g_marked_lines.push_back((int)idx);
}

static void cmd_next_mark(const std::string &args, const std::string &loc)
{
    (void)args; (void)loc;
    auto vis = visible_lines();
    for (size_t k = g_session.top_line + 1; k < vis.size(); k++) {
        if (g_marks[vis[k]]) {
            g_session.top_line = (int)k;
            return;
        }
    }
    fputs("  info: no more user, user-expr, meta, partition, sticky bookmarks after here\n",
          stderr);
}

static void cmd_prev_mark(const std::string &args, const std::string &loc)
{
    (void)args; (void)loc;
    auto vis = visible_lines();
    for (int k = g_session.top_line - 1; k >= 0; k--) {
        if (g_marks[vis[k]]) {
            g_session.top_line = k;
            return;
        }
    }
    fputs("  info: no more user, user-expr, meta, partition, sticky bookmarks before here\n",
          stderr);
}

static void cmd_goto(const std::string &args, const std::string &name,
                     const std::string &loc)
{
    std::string a = trim(args);
    if (a.empty()) {
        cmd_error("expecting a line number or timestamp", "", name, args, loc);
        return;
    }
    auto vis = visible_lines();
    if (a[0] == '#') {
        // anchor
        for (size_t k = 0; k < vis.size(); k++) {
            (void)k;
        }
        return;
    }
    if (a[a.size() - 1] == '%') {
        std::string num = a.substr(0, a.size() - 1);
        char *end = nullptr;
        double pct = strtod(num.c_str(), &end);
        if (end == num.c_str()) {
            cmd_error("invalid argument: " + a,
                      "expecting line number/percentage, timestamp, or relative time",
                      name, args, loc);
            return;
        }
        size_t idx = (size_t)(pct / 100.0 * (double)vis.size());
        g_session.top_line = (int)idx;
        return;
    }
    char *end = nullptr;
    long ln = strtol(a.c_str(), &end, 10);
    if (end != nullptr && *end == '\0' && !a.empty()) {
        g_session.top_line = (int)ln;
        return;
    }
    // timestamp
    auto ts = parse_timestamp(a, true);
    if (ts.has_value()) {
        for (size_t k = 0; k < vis.size(); k++) {
            if (g_view[vis[k]].time >= ts->usecs) {
                g_session.top_line = (int)k;
                return;
            }
        }
        g_session.top_line = (int)vis.size();
        return;
    }
    cmd_error("invalid argument: " + a,
              "expecting line number/percentage, timestamp, or relative time",
              name, args, loc);
}

static void cmd_set_min_log_level(const std::string &args, const std::string &name,
                                  const std::string &loc)
{
    std::string lv = to_lower(trim(args));
    int idx = level_index(lv);
    if (idx < 0) {
        cmd_error("invalid argument: " + args, "", name, args, loc);
        return;
    }
    g_min_level = idx;
}

static void cmd_current_time(const std::string &args, const std::string &name,
                             const std::string &loc)
{
    (void)args; (void)name; (void)loc;
    usecs_t now = (usecs_t)time(nullptr) * 1000000LL;
    struct tm tm = utc_break(now);
    char buf[128];
    strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y", &tm);
    g_session.echo_used = true;
    printf("%s (%lld)\n", buf, (long long)(now / 1000000LL));
    fflush(stdout);
}

static void cmd_unix_time(const std::string &args, const std::string &name,
                          const std::string &loc)
{
    std::string a = trim(args);
    char *end = nullptr;
    long long v = strtoll(a.c_str(), &end, 10);
    if (a.empty() || (end != nullptr && *end != '\0')) {
        cmd_error("invalid argument: " + args, "", name, args, loc);
        return;
    }
    struct tm tm = utc_break((usecs_t)v * 1000000LL);
    char buf[128];
    strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y", &tm);
    g_session.echo_used = true;
    printf("%s (%lld)\n", buf, v);
    fflush(stdout);
}

static void run_shell(const std::string &cmdline, const std::string &name,
                      const std::string &args, const std::string &loc)
{
    std::string output;
    int in_pipe[2], out_pipe[2];
    if (pipe(in_pipe) < 0 || pipe(out_pipe) < 0) return;
    pid_t pid = fork();
    if (pid == 0) {
        close(in_pipe[1]);
        close(out_pipe[0]);
        dup2(in_pipe[0], 0);
        dup2(out_pipe[1], 1);
        close(in_pipe[0]);
        close(out_pipe[1]);
        execl("/bin/sh", "sh", "-c", cmdline.c_str(), (char *)nullptr);
        _exit(127);
    }
    close(in_pipe[0]);
    close(out_pipe[1]);
    close(in_pipe[1]);
    char buf[4096];
    ssize_t n;
    while ((n = read(out_pipe[0], buf, sizeof(buf))) > 0) output.append(buf, n);
    close(out_pipe[0]);
    int status = 0;
    waitpid(pid, &status, 0);
    if (name == "sh") {
        g_session.echo_used = true;
        fputs(output.c_str(), stdout);
        fflush(stdout);
        (void)args; (void)loc;
    }
}

void run_command(const std::string &cmd, const std::string &loc)
{
    std::string name = cmd;
    std::string args;
    size_t sp = cmd.find(' ');
    if (sp != std::string::npos) {
        name = cmd.substr(0, sp);
        args = cmd.substr(sp + 1);
    }
    if (name.empty()) name = cmd;

    if (name == "help") {
        print_internal_help();
        g_session.echo_used = true;
        return;
    }
    if (name == "echo") {
        cmd_echo(args);
