static void cmd_echo(const std::string &args)
{
    bool no_nl = false;
    std::string msg = args;
    if (starts_with(msg, "-n ")) {
        no_nl = true;
        msg = msg.substr(3);
    } else if (msg == "-n") {
        no_nl = true;
        msg = "";
    }
    g_session.echo_used = true;
    fputs(msg.c_str(), stdout);
    if (!no_nl) fputc('\n', stdout);
    fflush(stdout);
}

static void cmd_filter(const std::string &name, const std::string &args,
                       const std::string &loc)
{
    std::string pat = trim(args);
    if (pat.empty()) {
        cmd_error("expecting a regular expression to filter", "", name, args, loc);
        return;
    }
    if (name == "delete-filter" || name == "disable-filter" || name == "enable-filter") {
        bool found = false;
        for (size_t i = 0; i < g_filters.size(); i++) {
            if (g_filters[i].second == pat) {
                found = true;
                if (name == "delete-filter") {
                    g_filters.erase(g_filters.begin() + i);
                    g_filter_enabled.erase(g_filter_enabled.begin() + i);
                    i--;
                } else {
                    g_filter_enabled[i] = name == "enable-filter";
                }
            }
        }
        if (!found) {
            cmd_error("unable to find filter with value \xe2\x80\x9c" + pat + "\xe2\x80\x9d",
                      "", name, args, loc);
        }
        return;
    }
    if (name == "filter-expr" || name == "clear-filter-expr") {
        return;
    }
    if (name == "toggle-filtering") {
        g_session.filtering_enabled = !g_session.filtering_enabled;
        return;
    }
    std::string type = name == "filter-in" ? "in" : "out";
    for (size_t i = 0; i < g_filters.size(); i++) {
        if (g_filters[i].first == type && g_filters[i].second == pat) {
            g_filter_enabled[i] = true;
            return;
        }
    }
    g_filters.push_back({type, pat});
    g_filter_enabled.push_back(true);
}

static void cmd_write_view(const std::string &args)
{
    std::string path = trim(args);
    std::string data;
    auto vis = visible_lines();
    for (size_t i = 0; i < vis.size(); i++) {
        data += g_view[vis[i]].text;
        data += '\n';
    }
    if (path.empty()) {
        fputs(data.c_str(), stdout);
        fflush(stdout);
        g_session.view_printed = true;
        return;
    }
    write_file(path, data, false);
}

static void cmd_write_to(const std::string &name, const std::string &args,
