{
    std::string path = trim(args);
    if (g_marked_lines.empty()) {
        cmd_error("no lines marked to write, use 'm' to mark lines", "", name, args, loc);
        return;
    }
    // Collect the raw content of the marked lines, grouped by file
    std::string data;
    for (size_t i = 0; i < g_view.size(); i++) {
        if (!g_marks[i]) continue;
        data += g_view[i].text;
        data += '\n';
    }
    if (path.empty()) {
        fputs(data.c_str(), stdout);
        fflush(stdout);
        g_session.view_printed = true;
        return;
    }
    write_file(path, data, false);
}

static void cmd_mark(const std::string &args, const std::string &loc)
{
    (void)args; (void)loc;
    auto vis = visible_lines();
    if (g_session.top_line >= (int)vis.size()) return;
    size_t idx = vis[g_session.top_line];
    g_marks[idx] = !g_marks[idx];
    if (g_marks[idx]) g_marked_lines.push_back((int)idx);
}

static void cmd_next_mark(const std::string &args, const std::string &loc)
{
    (void)args; (void)loc;
    auto vis = visible_lines();
    for (size_t k = g_session.top_line + 1; k < vis.size(); k++) {
        if (g_marks[vis[k]]) {
            g_session.top_line = (int)k;
            return;
        }
    }
    fputs("  info: no more user, user-expr, meta, partition, sticky bookmarks after here\n",
          stderr);
}

static void cmd_prev_mark(const std::string &args, const std::string &loc)
{
    (void)args; (void)loc;
    auto vis = visible_lines();
    for (int k = g_session.top_line - 1; k >= 0; k--) {
        if (g_marks[vis[k]]) {
            g_session.top_line = k;
            return;
        }
    }
    fputs("  info: no more user, user-expr, meta, partition, sticky bookmarks before here\n",
          stderr);
}

static void cmd_goto(const std::string &args, const std::string &name,
                     const std::string &loc)
{
    std::string a = trim(args);
    if (a.empty()) {
        cmd_error("expecting a line number or timestamp", "", name, args, loc);
        return;
    }
    auto vis = visible_lines();
    if (a[0] == '#') {
        // anchor
        for (size_t k = 0; k < vis.size(); k++) {
            (void)k;
        }
        return;
    }
    if (a[a.size() - 1] == '%') {
        std::string num = a.substr(0, a.size() - 1);
        char *end = nullptr;
        double pct = strtod(num.c_str(), &end);
        if (end == num.c_str()) {
            cmd_error("invalid argument: " + a,
                      "expecting line number/percentage, timestamp, or relative time",
                      name, args, loc);
            return;
        }
        size_t idx = (size_t)(pct / 100.0 * (double)vis.size());
        g_session.top_line = (int)idx;
        return;
    }
    char *end = nullptr;
    long ln = strtol(a.c_str(), &end, 10);
    if (end != nullptr && *end == '\0' && !a.empty()) {
        g_session.top_line = (int)ln;
        return;
    }
    // timestamp
    auto ts = parse_timestamp(a, true);
    if (ts.has_value()) {
        for (size_t k = 0; k < vis.size(); k++) {
            if (g_view[vis[k]].time >= ts->usecs) {
                g_session.top_line = (int)k;
                return;
            }
        }
        g_session.top_line = (int)vis.size();
        return;
    }
    cmd_error("invalid argument: " + a,
              "expecting line number/percentage, timestamp, or relative time",
              name, args, loc);
}

static void cmd_set_min_log_level(const std::string &args, const std::string &name,
                                  const std::string &loc)
{
    std::string lv = to_lower(trim(args));
    int idx = level_index(lv);
    if (idx < 0) {
        cmd_error("invalid argument: " + args, "", name, args, loc);
        return;
    }
    g_min_level = idx;
}

static void cmd_current_time(const std::string &args, const std::string &name,
                             const std::string &loc)
{
    (void)args; (void)name; (void)loc;
    usecs_t now = (usecs_t)time(nullptr) * 1000000LL;
    struct tm tm = utc_break(now);
    char buf[128];
    strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y", &tm);
    g_session.echo_used = true;
    printf("%s (%lld)\n", buf, (long long)(now / 1000000LL));
    fflush(stdout);
}

static void cmd_unix_time(const std::string &args, const std::string &name,
                          const std::string &loc)
{
    std::string a = trim(args);
    char *end = nullptr;
    long long v = strtoll(a.c_str(), &end, 10);
    if (a.empty() || (end != nullptr && *end != '\0')) {
        cmd_error("invalid argument: " + args, "", name, args, loc);
        return;
    }
    struct tm tm = utc_break((usecs_t)v * 1000000LL);
    char buf[128];
    strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y", &tm);
    g_session.echo_used = true;
    printf("%s (%lld)\n", buf, v);
    fflush(stdout);
}

static void run_shell(const std::string &cmdline, const std::string &name,
                      const std::string &args, const std::string &loc)
{
    std::string output;
    int in_pipe[2], out_pipe[2];
    if (pipe(in_pipe) < 0 || pipe(out_pipe) < 0) return;
    pid_t pid = fork();
    if (pid == 0) {
        close(in_pipe[1]);
        close(out_pipe[0]);
        dup2(in_pipe[0], 0);
        dup2(out_pipe[1], 1);
        close(in_pipe[0]);
        close(out_pipe[1]);
        execl("/bin/sh", "sh", "-c", cmdline.c_str(), (char *)nullptr);
        _exit(127);
    }
    close(in_pipe[0]);
    close(out_pipe[1]);
    close(in_pipe[1]);
    char buf[4096];
    ssize_t n;
    while ((n = read(out_pipe[0], buf, sizeof(buf))) > 0) output.append(buf, n);
    close(out_pipe[0]);
    int status = 0;
    waitpid(pid, &status, 0);
    if (name == "sh") {
        g_session.echo_used = true;
        fputs(output.c_str(), stdout);
        fflush(stdout);
        (void)args; (void)loc;
    }
}

void run_command(const std::string &cmd, const std::string &loc)
{
    std::string name = cmd;
    std::string args;
    size_t sp = cmd.find(' ');
    if (sp != std::string::npos) {
        name = cmd.substr(0, sp);
        args = cmd.substr(sp + 1);
    }
    if (name.empty()) name = cmd;

    if (name == "help") {
        print_internal_help();
        g_session.echo_used = true;
        return;
    }
    if (name == "echo") {
        cmd_echo(args);
        return;
    }
    if (name == "alt-msg" || name == "redraw" || name == "rebuild" || name == "quit") {
        if (name == "quit") g_session.quit = true;
        return;
    }
    if (name == "filter-in" || name == "filter-out" || name == "delete-filter" ||
        name == "disable-filter" || name == "enable-filter" || name == "filter-expr" ||
        name == "clear-filter-expr" || name == "toggle-filtering") {
        if (name == "filter-expr" || name == "clear-filter-expr" ||
            name == "toggle-filtering") {
            return;
        }
        cmd_filter(name, args, loc);
        return;
    }
    if (name == "set-min-log-level") {
        cmd_set_min_log_level(args, name, loc);
        return;
    }
    if (name == "goto") {
        cmd_goto(args, name, loc);
        return;
    }
    if (name == "relative-goto") {
        std::string a = trim(args);
        char *end = nullptr;
        long delta = strtol(a.c_str(), &end, 10);
        if (end == nullptr || *end != '\0') {
            cmd_error("invalid argument: " + args, "", name, args, loc);
            return;
        }
        g_session.top_line += (int)delta;
        return;
    }
    if (name == "mark") {
        cmd_mark(args, loc);
        return;
    }
    if (name == "next-mark") {
        cmd_next_mark(args, loc);
        return;
    }
    if (name == "prev-mark") {
        cmd_prev_mark(args, loc);
        return;
    }
    if (name == "hide-unmarked-lines") {
        g_session.hide_unmarked = true;
        return;
    }
    if (name == "show-unmarked-lines") {
        g_session.hide_unmarked = false;
        return;
    }
    if (name == "write-view-to" || name == "write-screen-to") {
        cmd_write_view(args);
        return;
    }
    if (name == "write-to") {
        cmd_write_to(name, args, loc);
        return;
    }
    if (name == "write-raw-to" || name == "write-jsonlines-to") {
        cmd_write_to(name, args, loc);
        return;
    }
    if (name == "write-csv-to" || name == "write-json-to" || name == "write-json-cols-to" ||
        name == "write-table-to") {
        if (g_db == nullptr || !g_db->has_result) {
            cmd_error("no query result to write, use ';' to execute a query", "", name,
                      args, loc);
            return;
        }
        std::string data;
        if (name == "write-csv-to") data = g_db->render_csv();
        else if (name == "write-json-to") data = g_db->render_json();
        else if (name == "write-json-cols-to") data = g_db->render_json();
        else data = g_db->render_table();
        std::string path = trim(args);
        if (path.empty()) {
            fputs(data.c_str(), stdout);
            fflush(stdout);
            g_session.view_printed = true;
        } else {
            write_file(path, data, false);
        }
        return;
    }
    if (name == "append-to") {
        std::string data;
        for (size_t i = 0; i < g_view.size(); i++) {
            if (!g_marks[i]) continue;
            data += g_view[i].text;
            data += '\n';
        }
        if (g_marked_lines.empty()) {
            cmd_error("no lines marked to write, use 'm' to mark lines", "", name, args, loc);
            return;
        }
        write_file(trim(args), data, true);
        return;
    }
    if (name == "current-time") {
        cmd_current_time(args, name, loc);
        return;
    }
    if (name == "unix-time") {
        cmd_unix_time(args, name, loc);
        return;
    }
    if (name == "sh") {
        std::string cmdline = args;
        if (starts_with(cmdline, "--name=")) {
            size_t sp2 = cmdline.find(' ');
            if (sp2 == std::string::npos) {
                cmd_error("expecting a command-line to execute", "", name, args, loc);
                return;
            }
            cmdline = cmdline.substr(sp2 + 1);
        }
        run_shell(cmdline, name, args, loc);
        return;
    }
    if (name == "pipe-to" || name == "pipe-line-to") {
        run_shell(args, "", args, loc);
        return;
    }
    if (name == "switch-to-view" || name == "toggle-view") {
        std::string v = trim(args);
        if (v == "text") {
            if (g_text_files.empty()) {
                g_session.current_view_is_text = false;
                return;
            }
            g_session.current_view_is_text = true;
        } else if (v == "log") {
            g_session.current_view_is_text = false;
        } else if (v == "help") {
            print_internal_help();
            g_session.echo_used = true;
        } else if (v == "db" || v == "schema" || v == "pretty" || v == "spectro" ||
                   v == "timeline" || v == "histogram") {
            if (v == "schema") {
                g_session.echo_used = true;
                fputs(g_db != nullptr ? g_db->schema_text() : "", stdout);
                fflush(stdout);
            } else if (v == "histogram") {
                g_session.echo_used = true;
                print_histogram();
            } else if (v == "pretty") {
                g_session.current_view_is_text = false;
            }
        } else {
            DisplayError e;
            e.error = "invalid view name -- " + v;
            e.location = loc;
            e.context.push_back(":" + name + (args.empty() ? "" : " " + args));
            const CmdDoc *d = doc_for(name);
            if (d != nullptr) {
                e.help_synopsis = d->synopsis;
                e.help_desc = d->desc;
            }
            report_error(e);
            g_session.error_seen = true;
        }
        return;
    }
    if (name == "export-session-to" || name == "save-session" || name == "load-session" ||
        name == "session" || name == "reset-session") {
        return;
    }
    if (name == "hide-fields" || name == "show-fields" || name == "hide-file" ||
        name == "show-file" || name == "highlight" || name == "clear-highlight" ||
        name == "highlight-field" || name == "clear-highlight-field" ||
        name == "comment" || name == "clear-comment" || name == "tag" || name == "untag" ||
        name == "delete-tags" || name == "partition-name" || name == "clear-partition" ||
        name == "annotate" || name == "summarize" || name == "spectrogram" ||
        name == "zoom-to" || name == "next-section" || name == "prev-section" ||
        name == "next-location" || name == "prev-location" ||
        name == "set-text-view-mode" || name == "enable-word-wrap" ||
        name == "disable-word-wrap" || name == "hide-in-timeline" ||
        name == "show-in-timeline" || name == "config" || name == "reset-config" ||
        name == "eval" || name == "session" || name == "adjust-log-time" ||
        name == "clear-adjusted-log-time" || name == "hide-lines-before" ||
        name == "hide-lines-after" || name == "show-lines-before-and-after" ||
        name == "convert-time-to" || name == "set-file-timezone" ||
        name == "clear-file-timezone" || name == "redirect-to" ||
        name == "external-access" || name == "external-access-login" ||
        name == "add-source-path" || name == "breakpoint" || name == "clear-breakpoint" ||
        name == "enable-breakpoint" || name == "disable-breakpoint" ||
        name == "toggle-breakpoint" || name == "mark-expr" || name == "clear-mark-expr" ||
        name == "create-logline-table" || name == "delete-logline-table" ||
        name == "create-search-table" || name == "delete-search-table" ||
        name == "hide-unmarked-lines" || name == "show-only-this-file" ||
        name == "prompt" || name == "xopen" || name == "open" || name == "close") {
        return;
    }
    unknown_command(name, loc);
}

void print_final_output()
{
    if (g_session.echo_used) return;
    if (g_db != nullptr && g_db->has_result) {
        fputs(g_db->render().c_str(), stdout);
        fflush(stdout);
        return;
    }
    if (g_session.current_view_is_text && !g_text_files.empty()) {
        for (size_t fi = 0; fi < g_files.size(); fi++) {
            if (std::find(g_text_files.begin(), g_text_files.end(),
                          g_files[fi]->path) == g_text_files.end()) {
                continue;
            }
            for (auto &l : g_files[fi]->lines) {
                fputs(l.c_str(), stdout);
                fputc('\n', stdout);
            }
        }
        fflush(stdout);
        return;
    }
    rebuild_view();
    auto vis = visible_lines();
    std::string out;
    for (size_t k = g_session.top_line; k < vis.size(); k++) {
        out += g_view[vis[k]].text;
        out += '\n';
    }
    fputs(out.c_str(), stdout);
    fflush(stdout);
}

