static std::vector<std::string> fmt_cols(const std::string &fmt)
{
    std::vector<std::string> cols;
    cols.push_back("log_line");
    cols.push_back("log_time");
    cols.push_back("log_level");
    if (fmt == "syslog_log") {
        for (const char *c : {"log_hostname", "log_msgid", "log_pid", "log_pri",
                              "log_procname", "log_struct", "log_syslog_tag",
                              "syslog_version"}) {
            cols.push_back(c);
        }
    } else if (fmt == "access_log") {
        for (const char *c : {"c_ip", "cs_method", "cs_referer", "cs_uri_query",
                              "cs_uri_stem", "cs_user_agent", "cs_username",
                              "cs_version", "sc_bytes", "sc_status", "cs_host"}) {
            cols.push_back(c);
        }
    }
    for (const char *c : {"log_part", "log_idle_msecs", "log_mark", "log_comment",
                          "log_tags", "log_annotations", "log_filters"}) {
        cols.push_back(c);
    }
    cols.push_back("log_text");
    return cols;
}

void db_set_files(DbView &view, const std::vector<std::shared_ptr<LogFile>> &files)
{
    static std::vector<std::shared_ptr<LogFile>> *holder = nullptr;
    holder = const_cast<std::vector<std::shared_ptr<LogFile>> *>(&files);
    // create the virtual tables
    std::set<std::string> formats;
    for (auto &f : files) {
        if (f != nullptr && f->format != nullptr) formats.insert(f->format->name);
    }
    for (auto &fname : formats) {
        auto spec = std::make_shared<VTabSpec>();
        spec->name = fname;
        spec->module = "logvtab_impl";
        spec->cols = fmt_cols(fname);
        spec->text_col = true;
        spec->files = &files;
        spec->focused_only = false;
        g_vtabs.push_back(spec);
        std::string sql = "CREATE VIRTUAL TABLE \"" + fname + "\" USING logvtab_impl();";
        char *err = nullptr;
        if (sqlite3_exec(view.db, sql.c_str(), nullptr, nullptr, &err) != SQLITE_OK) {
            if (err != nullptr) sqlite3_free(err);
        }
    }
    // logline
    {
        auto spec = std::make_shared<VTabSpec>();
        spec->name = "logline";
        spec->module = "logvtab_impl";
        spec->cols = fmt_cols(formats.empty() ? "generic_log" : *formats.begin());
        spec->text_col = true;
        spec->files = &files;
        spec->focused_only = true;
        g_vtabs.push_back(spec);
        std::string sql = "CREATE VIRTUAL TABLE logline USING logvtab_impl();";
        char *err = nullptr;
        if (sqlite3_exec(view.db, sql.c_str(), nullptr, nullptr, &err) != SQLITE_OK) {
            if (err != nullptr) sqlite3_free(err);
        }
    }
    for (auto &f : files) {
        if (f == nullptr) continue;
        f->vtab_index = -1;
        for (size_t i = 0; i < g_vtabs.size(); i++) {
            if (g_vtabs[i]->name == (f->format ? f->format->name : "")) {
                f->vtab_index = (int)i;
            }
        }
    }
    recompute_focus();
}

static std::string quote_sql(const std::string &s)
{
    std::string out;
    for (char c : s) {
        if (c == '\'') out += "''";
        else out += c;
    }
    return out;
}

void run_sql(const std::string &sql, const std::string &loc, DbView &view)
{
    if (view.db == nullptr && !view.open()) {
        DisplayError e;
        e.error = "failed to compile SQL statement";
        e.reason = view.last_error;
        e.location = loc;
        e.context.push_back(sql);
        report_error(e);
        g_session.error_seen = true;
        return;
    }
    sqlite3_stmt *stmt = nullptr;
    const char *tail = nullptr;
    int rc = sqlite3_prepare_v2(view.db, sql.c_str(), -1, &stmt, &tail);
    if (rc != SQLITE_OK) {
        DisplayError e;
        e.error = "failed to compile SQL statement";
        e.reason = sqlite3_errmsg(view.db);
        e.location = loc;
        e.context.push_back(sql);
        report_error(e);
        g_session.error_seen = true;
        return;
    }
    DbResult res;
    bool have_cols = false;
    while (true) {
        rc = sqlite3_step(stmt);
        if (rc == SQLITE_ROW) {
            int nc = sqlite3_column_count(stmt);
            if (!have_cols) {
                for (int i = 0; i < nc; i++) {
                    DbCol c;
                    c.name = sqlite3_column_name(stmt, i);
                    res.cols.push_back(c);
                }
                have_cols = true;
            }
            std::vector<std::string> row;
            std::vector<int> types;
            for (int i = 0; i < nc; i++) {
                int t = sqlite3_column_type(stmt, i);
                if (t == SQLITE_NULL) {
                    row.push_back("<NULL>");
                    types.push_back(3);
                } else if (t == SQLITE_INTEGER || t == SQLITE_FLOAT) {
                    const unsigned char *v = sqlite3_column_text(stmt, i);
                    row.push_back(v != nullptr ? (const char *)v : "");
                    types.push_back(t == SQLITE_INTEGER ? 1 : 2);
                } else {
                    const unsigned char *v = sqlite3_column_text(stmt, i);
                    row.push_back(v != nullptr ? (const char *)v : "");
                    types.push_back(0);
                }
            }
            res.rows.push_back(row);
            res.types.push_back(types);
        } else if (rc == SQLITE_DONE) {
            break;
        } else {
            sqlite3_finalize(stmt);
            DisplayError e;
            e.error = "failed to execute SQL statement";
            e.reason = sqlite3_errmsg(view.db);
            e.location = loc;
            e.context.push_back(sql);
            report_error(e);
            g_session.error_seen = true;
            return;
        }
    }
    sqlite3_finalize(stmt);
    view.result = res;
    view.has_result = have_cols;
    if (!have_cols) view.has_result = false;
}

static void script_error(const std::string &spec, const std::string &loc,
                         const std::string &msg, const std::string &reason)
{
    DisplayError e;
    e.error = msg;
    e.reason = reason;
    e.location = loc;
    e.context.push_back("|" + spec);
    report_error(e);
    g_session.error_seen = true;
}

void run_script(const std::string &spec, const std::string &loc, DbView &db,
                const Options &opts)
{
    (void)opts;
    std::string path = spec;
    std::vector<std::string> script_args;
    size_t sp = spec.find(' ');
    if (sp != std::string::npos) {
        path = spec.substr(0, sp);
        // split the rest into arguments
        std::string rest = spec.substr(sp + 1);
        std::string cur;
        for (size_t i = 0; i <= rest.size(); i++) {
            if (i == rest.size() || rest[i] == ' ') {
                if (!cur.empty()) script_args.push_back(cur);
                cur.clear();
            } else {
                cur += rest[i];
            }
        }
    }
    std::string content;
    bool ok = true;
    if (path == "-" || starts_with(path, "exec:")) {
        if (starts_with(path, "exec:")) {
            // run the shell command and use its output as log content
            std::string cmdline = spec.substr(6);
            int out_pipe[2];
            if (pipe(out_pipe) < 0) return;
            pid_t pid = fork();
            if (pid == 0) {
                close(out_pipe[0]);
                dup2(out_pipe[1], 1);
                close(out_pipe[1]);
                execl("/bin/sh", "sh", "-c", cmdline.c_str(), (char *)nullptr);
                _exit(127);
            }
            close(out_pipe[1]);
            char buf[4096];
            ssize_t n;
            while ((n = read(out_pipe[0], buf, sizeof(buf))) > 0) content.append(buf, n);
            close(out_pipe[0]);
            int status;
            waitpid(pid, &status, 0);
            ok = true;
        } else {
            content = read_file("-");
            ok = true;
        }
    } else {
        FILE *fp = fopen(path.c_str(), "rb");
        if (fp == nullptr) {
            script_error(spec, loc, "unable to open script: " + path,
                         "No such file or directory");
            return;
        }
        char buf[4096];
        size_t n;
        while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) content.append(buf, n);
        fclose(fp);
    }
    (void)script_args;
    // execute each line
    int idx = 0;
    size_t pos = 0;
    while (pos <= content.size()) {
        size_t eol = content.find('\n', pos);
        std::string line = content.substr(pos, eol == std::string::npos ? std::string::npos
                                                                       : eol - pos);
        pos = eol == std::string::npos ? content.size() + 1 : eol + 1;
        if (!line.empty() && line.back() == '\r') line.pop_back();
        idx++;
        if (line.empty()) continue;
        if (line[0] == ':') {
            run_command(line.substr(1), loc);
        } else if (line[0] == ';') {
            run_sql(line.substr(1), loc, db);
        } else if (line[0] == '|') {
            run_script(line.substr(1), loc, db, opts);
        } else {
            script_error(spec, loc, "invalid command in script file: " + path,
                         "missing command type prefix");
            return;
        }
        if (g_session.error_seen) return;
    }
}

void print_histogram()
{
    std::string out;
    // group the log messages by hour
    std::map<usecs_t, int> counts;
    int total_normal = 0, total_errors = 0, total_warnings = 0;
    for (auto &f : g_files) {
        if (f == nullptr || f->is_text) continue;
        for (auto &msg : f->messages) {
            if (!msg.has_time) continue;
            usecs_t hour = (msg.time / 3600000000LL) * 3600000000LL;
            counts[hour]++;
            if (msg.level == "error") total_errors++;
            else if (msg.level == "warning") total_warnings++;
            else total_normal++;
        }
    }
    for (auto &kv : counts) {
        struct tm tm = utc_break(kv.first);
        char buf[128];
        strftime(buf, sizeof(buf), "%a %b %d %H:%M:%S %Y", &tm);
        int errs = 0, warns = 0;
        for (auto &f : g_files) {
            if (f == nullptr || f->is_text) continue;
            for (auto &msg : f->messages) {
                if (!msg.has_time) continue;
                usecs_t hour = (msg.time / 3600000000LL) * 3600000000LL;
                if (hour != kv.first) continue;
                if (msg.level == "error") errs++;
                else if (msg.level == "warning") warns++;
            }
        }
        out += fmt_str("%s %s%11d %s%9d %s%9d %s%9d\n", buf, "", kv.second, "", errs,
                       "", warns, "", 0);
    }
    fputs(out.c_str(), stdout);
    fflush(stdout);
}

void recompute_focus()
{
    // Determine the focused message for the logline table
    g_focused_line_number = 0;
    for (auto &f : g_files) {
        if (f != nullptr && !f->is_text && !f->messages.empty()) {
            g_focused_line_number = f->messages[0].line_number;
            break;
        }
    }
}

}  // namespace lnav
