#include "embed.hh"
#include <zlib.h>
#include <cstring>

namespace lnav {

static int b64val(char c)
{
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

static std::string b64decode(const char *s)
{
    std::string out;
    int val = 0, bits = 0;
    for (const char *p = s; *p != '\0'; p++) {
        int v = b64val(*p);
        if (v < 0) continue;
        val = (val << 6) | v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            out += (char)((val >> bits) & 0xff);
        }
    }
    return out;
}

std::string gunzip_data(const unsigned char *data, size_t len)
{
    std::string out;
    z_stream_s zs;
    memset(&zs, 0, sizeof(zs));
    if (inflateInit2(&zs, 47) != Z_OK) return out;
    zs.next_in = (Bytef *)data;
    zs.avail_in = (uInt)len;
    char buf[65536];
    int rc;
    do {
        zs.next_out = (Bytef *)buf;
        zs.avail_out = sizeof(buf);
        rc = inflate(&zs, Z_NO_FLUSH);
        out.append(buf, sizeof(buf) - zs.avail_out);
    } while (rc == Z_OK && zs.avail_out == 0);
    inflateEnd(&zs);
    return out;
}

std::string gunzip_b64(const char *b64)
{
    std::string raw = b64decode(b64);
    return gunzip_data((const unsigned char *)raw.data(), raw.size());
}

}  // namespace lnav
