{"command": "cd /workspace && cat > src/mgmt.cc <<'EOF'
#include "mgmt.hh"
#include "lnav.hh"
#include "help.hh"
#include "embed.hh"
#include "paths.hh"
#include "util.hh"
#include <dirent.h>
#include <sys/stat.h>

namespace lnav {

static const char *const MGMT_SUBCMDS[] = {
    "apps", "config", "format", "piper", "regex101", "crash", nullptr
};
static const char *const MGMT_SUBCMD_DESC[] = {
    "manage lnav apps",
    "perform operations on the lnav configuration",
    "perform operations on log file formats",
    "perform operations on piper storage",
    "create and edit log message regular expressions using regex101.com",
    "manage crash logs",
    nullptr
};

static void mgmt_error(const std::string &msg, int code)
{
    DisplayError e;
    e.error = msg;
    report_error(e);
    g_exit_code = code;
}

static void op_error(const std::string &msg, const std::vector<std::string> &ops)
{
    DisplayError e;
    e.error = msg;
    e.help_synopsis = "";
    e.help_desc.clear();
    e.help_raw.push_back(" = help: the available operations are:");
    for (auto &o : ops) {
        e.help_raw.push_back("          \xe2\x80\xa2 " + o);
    }
    report_error(e);
    g_exit_code = 1;
}

static std::vector<std::string> format_names()
{
    std::vector<std::string> out;
    for (int i = 0; fmtdesc_lines[i] != nullptr; i++) {
        std::string l = fmtdesc_lines[i];
        size_t tab = l.find('\t');
        out.push_back(l.substr(0, tab));
    }
    return out;
}

static std::string format_desc(const std::string &name)
{
    for (int i = 0; fmtdesc_lines[i] != nullptr; i++) {
        std::string l = fmtdesc_lines[i];
        size_t tab = l.find('\t');
        if (l.substr(0, tab) == name) {
            std::string d = l.substr(tab + 1);
            size_t colon = d.find(": ");
            if (colon != std::string::npos) d = d.substr(colon + 2);
            return d;
        }
    }
    return "";
}

static void print_format_list_note()
{
    std::string all;
    auto names = format_names();
    for (size_t i = 0; i < names.size(); i++) {
        if (i) all += ", ";
        all += names[i];
    }
    std::string prefix = " = note: the available formats are: ";
    size_t pos = 0;
    bool first = true;
    while (pos < all.size()) {
        size_t avail = first ? 70 - prefix.size() : 70 - 15;
        size_t end = pos;
        size_t last_break = std::string::npos;
        while (end < all.size() && end - pos <= avail) {
            if (all[end] == ',') last_break = end;
            end++;
        }
        if (end >= all.size()) {
            std::string chunk = all.substr(pos);
            fputs((first ? prefix : std::string(15, ' ')) + chunk + "\n", stderr);
            break;
        }
        if (last_break == std::string::npos) last_break = end - 1;
        std::string chunk = all.substr(pos, last_break - pos + 1);
        fputs((first ? prefix : std::string(15, ' ')) + chunk + "\n", stderr);
        pos = last_break + 1;
        while (pos < all.size() && all[pos] == ' ') pos++;
        first = false;
    }
}

static void unknown_format(const std::string &name)
{
    DisplayError e;
    e.error = "unknown format: " + name;
    report_error(e);
    g_exit_code = 1;
}

static void internal_format_error(const std::string &name)
{
    DisplayError e;
    e.error = "\xe2\x80\x9c" + name + "\xe2\x80\x9d is an internal format that is not defined in a configuration file";
    report_error(e);
    g_exit_code = 1;
}

static void print_mgmt_help(const char *prog)
{
    printf("The Logfile Navigator\n");
    printf("Usage: %s [OPTIONS] [SUBCOMMAND]\n", prog);
    printf("\n");
    printf("Options:\n");
    printf("  -h,--help                   Print this help message and exit\n");
    printf("  -d FILE                     Write debug messages to the given file.\n");
    printf("  -D                          Enable debugging of notcurses\n");
    printf("  -I TEXT:DIR ...             include paths\n");
    printf("  -q{0},-v{2}                 Control the verbosity\n");
    printf("  -V,--version                Display program version information and exit\n");
    printf("  -m                          Switch to the management CLI mode.\n");
    printf("\n");
    printf("Subcommands:\n");
    for (int i = 0; MGMT_SUBCMDS[i] != nullptr; i++) {
        printf("  %-27s %s\n", MGMT_SUBCMDS[i], MGMT_SUBCMD_DESC[i]);
    }
    printf("\n");
    printf("Version: lnav %s\n", LNAV_VERSION);
    printf("\n");
}

int mgmt_main(int argc, char **argv, const Options &opts)
{
    (void)opts;
    std::vector<std::string> args;
    for (int i = 1; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-m") continue;
        args.push_back(a);
    }
    std::vector<std::string> unexpected;
    std::string subcmd;
    std::vector<std::string> rest;
    for (size_t i = 0; i < args.size(); i++) {
        std::string &a = args[i];
        if (a == "-h" || a == "--help") {
            print_mgmt_help(g_prog_name);
            return 0;
        }
        if (a == "-V" || a == "--version") {
            print_version();
            return 0;
        }
        if (a == "-d" || a == "-I") {
            i++;
            continue;
        }
        if (a == "-D" || a == "-q" || a == "-v" || a == "-m") continue;
        if (a.size() > 1 && a[0] == '-') {
            unexpected.push_back(a);
            continue;
        }
        if (subcmd.empty()) subcmd = a;
        else rest.push_back(a);
    }
    if (!unexpected.empty()) {
        std::string list;
        for (size_t i = 0; i < unexpected.size(); i++) {
            if (i) list += " ";
            list += unexpected[i];
        }
        mgmt_error(std::string(unexpected.size() == 1
                                   ? "The following argument was not expected: "
                                   : "The following arguments were not expected: ") + list,
                   E_ARGS);
        return g_exit_code;
    }
    if (subcmd.empty()) {
        op_error("expecting an operation to perform",
                 {"apps: manage lnav apps",
                  "config: perform operations on the lnav configuration",
                  "format: perform operations on log file formats",
                  "piper: perform operations on piper storage",
                  "regex101: create and edit log message regular expressions using regex101.com",
                  "crash: manage crash logs"});
        return g_exit_code;
    }
    std::string op = rest.empty() ? "" : rest[0];
    std::string target = rest.size() > 1 ? rest[1] : "";

    if (subcmd == "config") {
        if (op.empty()) {
            op_error("expecting an operation related to lnav configuration",
                     {"get: print the current configuration",
                      "blame: print the configuration options and their source",
                      "file-options: print the options applied to specific files"});
            return g_exit_code;
        }
        if (op == "get") {
            fputs(cfg_json_text().c_str(), stdout);
            return 0;
        }
        if (op == "blame") {
            fputs(blame_txt_text().c_str(), stdout);
            return 0;
        }
        if (op == "file-options") {
            if (target.empty()) {
                DisplayError e;
                e.error = "Expecting a file path to check for options";
                report_error(e);
                g_exit_code = 1;
                return g_exit_code;
            }
            std::string full = target;
            if (target[0] != '/') {
                char buf[4096];
                if (getcwd(buf, sizeof(buf)) != nullptr) full = std::string(buf) + "/" + target;
            }
            struct stat st;
            if (stat(full.c_str(), &st) < 0) {
                DisplayError e;
                e.error = "Unable to get full path for file: " + target;
                e.reason = "No such file or directory";
                report_error(e);
                g_exit_code = 1;
                return g_exit_code;
            }
            return 0;
        }
        mgmt_error("The following argument was not expected: " + op, E_ARGS);
        return g_exit_code;
    }
    if (subcmd == "format") {
        if (target.empty()) {
            if (op.empty()) {
                DisplayError e;
                e.error = "expecting a format name to operate on";
                report_error(e);
                print_format_list_note();
                g_exit_code = 1;
                return g_exit_code;
            }
            auto names = format_names();
            bool found = false;
            for (auto &n : names) if (n == op) found = true;
            if (!found) {
                unknown_format(op);
                return g_exit_code;
            }
            DisplayError e;
            e.error = "expecting an operation to perform on the " + op + " format";
            e.help_raw.push_back(" = note: " + op + ": " + format_desc(op));
            e.help_raw.push_back(" = help: the available operations are:");
            e.help_raw.push_back("          \xe2\x80\xa2 get: print information about a format");
            e.help_raw.push_back("          \xe2\x80\xa2 test: test this format against a file");
            e.help_raw.push_back("          \xe2\x80\xa2 source: print the path of the first source file containing this format");
            e.help_raw.push_back("          \xe2\x80\xa2 sources: print the paths of all source files containing this format");
            e.help_raw.push_back("          \xe2\x80\xa2 regex: operate on the format's regular expressions");
            report_error(e);
            g_exit_code = 1;
            return g_exit_code;
        }
        // op is the format name, target is the operation
        std::string fmtname = op;
        std::string fmtop = target;
        auto names = format_names();
        bool found = false;
        for (auto &n : names) if (n == fmtname) found = true;
        if (!found) {
            unknown_format(fmtname);
            return g_exit_code;
        }
        if (fmtop == "get") {
            printf("%s: %s\n", fmtname.c_str(), format_desc(fmtname).c_str());
            return 0;
        }
        if (fmtop == "source" || fmtop == "sources" || fmtop == "regex" || fmtop == "test") {
            internal_format_error(fmtname);
            return g_exit_code;
        }
        mgmt_error("The following argument was not expected: " + fmtop, E_ARGS);
        return g_exit_code;
    }
    if (subcmd == "apps") {
        if (op.empty()) {
            op_error("expecting an operation related to lnav apps",
                     {"create: create a new app"});
            return g_exit_code;
        }
        if (op == "create") {
            std::string dir = get_config_dir() + "/configs/";
            DisplayError e;
            e.error = "app directory already exists: " + dir;
            e.help_raw.push_back(" = help: Delete the directory or choose a different name");
            report_error(e);
            g_exit_code = 1;
            return g_exit_code;
        }
        mgmt_error("The following argument was not expected: " + op, E_ARGS);
        return g_exit_code;
    }
    if (subcmd == "piper") {
        if (op.empty()) {
            op_error("expecting an operation related to piper storage",
                     {"list: print the available piper captures",
                      "clean: remove all piper captures"});
            return g_exit_code;
        }
        if (op == "clean") return 0;
        if (op == "list") {
            std::string dir = get_tmp_dir() + "/piper";
            DIR *d = opendir(dir.c_str());
            if (d == nullptr) return 0;
            closedir(d);
            fputs(fmt_str("  info: the following piper captures were found in:\n\t%s\n",
                          dir.c_str()).c_str(), stderr);
            return 0;
        }
        mgmt_error("The following argument was not expected: " + op, E_ARGS);
        return g_exit_code;
    }
    if (subcmd == "regex101") {
        if (op.empty()) {
            op_error("expecting an operation related to the regex101.com integration",
                     {"list: list the log format regular expression linked to entries on regex101.com",
                      "import: create a new format from a regular expression on regex101.com"});
            return g_exit_code;
        }
        return 0;
    }
    if (subcmd == "crash") {
        if (op.empty()) {
            op_error("expecting an operation related to crash logs",
                     {"upload: upload crash logs"});
            return g_exit_code;
        }
        if (op == "upload") {
            fputs("  uploaded 0 crash logs, thank you!\n", stdout);
            return 0;
        }
        mgmt_error("The following argument was not expected: " + op, E_ARGS);
        return g_exit_code;
    }
    mgmt_error("The following argument was not expected: " + subcmd, E_ARGS);
    return g_exit_code;
}

}  // namespace lnav
EOF
echo ok"}

