#include <sqlite3.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
static sqlite3_module mod;
typedef struct { sqlite3_vtab base; } VT;
typedef struct { sqlite3_vtab_cursor base; int row; int eof; } VC;
static int cConnect(sqlite3*db,void*a,int argc,const char*const*argv,sqlite3_vtab**pp,char**e){
  VT*vt=calloc(1,sizeof(VT));
  int rc=sqlite3_declare_vtab(db,"CREATE TABLE x(a INTEGER PRIMARY KEY,b TEXT HIDDEN)");
  fprintf(stderr,"declare rc=%d err=%s\n",rc,sqlite3_errmsg(db));
  if(rc){free(vt);return rc;}
  *pp=&vt->base; return SQLITE_OK;
}
static int cDisc(sqlite3_vtab*v){free(v);return SQLITE_OK;}
static int cBest(sqlite3_vtab*v,sqlite3_index_info*i){i->estimatedCost=1;return SQLITE_OK;}
static int cOpen(sqlite3_vtab*v,sqlite3_vtab_cursor**c){VC*cu=calloc(1,sizeof(VC));cu->base.pVtab=v;*c=&cu->base;return SQLITE_OK;}
static int cClose(sqlite3_vtab_cursor*c){free(c);return SQLITE_OK;}
static int cFilter(sqlite3_vtab_cursor*c,int n,const char*s,int a,sqlite3_value**v){((VC*)c)->row=0;((VC*)c)->eof=0;return SQLITE_OK;}
static int cNext(sqlite3_vtab_cursor*c){((VC*)c)->row++;if(((VC*)c)->row>1)((VC*)c)->eof=1;return SQLITE_OK;}
static int cEof(sqlite3_vtab_cursor*c){return ((VC*)c)->eof;}
static int cCol(sqlite3_vtab_cursor*c,sqlite3_context*ctx,int i){sqlite3_result_int(ctx,((VC*)c)->row);return SQLITE_OK;}
static int cRowid(sqlite3_vtab_cursor*c,sqlite3_int64*r){*r=((VC*)c)->row;return SQLITE_OK;}
int main(){
  sqlite3*db; sqlite3_open(":memory:",&db);
  memset(&mod,0,sizeof(mod));
  mod.iVersion=1; mod.xCreate=cConnect; mod.xConnect=cConnect; mod.xBestIndex=cBest;
  mod.xDisconnect=cDisc; mod.xDestroy=cDisc; mod.xOpen=cOpen; mod.xClose=cClose;
  mod.xFilter=cFilter; mod.xNext=cNext; mod.xEof=cEof; mod.xColumn=cCol; mod.xRowid=cRowid;
  char*err=0;
  int rc=sqlite3_create_module(db,"t",&mod,0);
  printf("create_module rc=%d\n",rc);
  rc=sqlite3_exec(db,"CREATE VIRTUAL TABLE v USING t();",0,0,&err);
  printf("create rc=%d err=%s\n",rc,err?err:"");
  rc=sqlite3_exec(db,"SELECT count(*) FROM v;",0,0,&err);
  printf("select rc=%d err=%s\n",rc,err?err:"");
  return 0;
}
EOF
