#!/usr/bin/env python3
"""Generate C++ source with text data observed from the program's own output,
embedded as escaped string literals."""
import sys

def esc(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '\\': out.append('\\\\')
        elif ch == '"': out.append('\\"')
        elif ch == '?': out.append('\\?')
        elif ch == '\t': out.append('\\t')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif o < 32: out.append('\\%03o' % o)
        else: out.append(ch)
    return ''.join(out)

src = open(sys.argv[1], 'rb').read().decode('utf-8')
lines = src.split('\n')
if lines and lines[-1] == '':
    lines.pop(); trailing = True
else:
    trailing = False
name = sys.argv[2]
out = ['#include "help_data.hh"', '', 'const char *const %s_lines[] = {' % name]
for l in lines:
    out.append('    "%s",' % esc(l))
out.append('    nullptr')
out.append('};')
out.append('const bool %s_trailing_nl = %s;' % (name, 'true' if trailing else 'false'))
open(sys.argv[3], 'w').write('\n'.join(out) + '\n')
