{
    std::string out;
    out += "ATTACH DATABASE '' AS 'main';\\n";
    out += "ATTACH DATABASE '' AS 'lnav_db';\\n";
    if (db == nullptr) return out;
    sqlite3_stmt *stmt = nullptr;
    if (sqlite3_prepare_v2(db,
                           "SELECT type, name, sql FROM sqlite_master ORDER BY rowid",
                           -1, &stmt, nullptr) != SQLITE_OK) {
        return out;
    }
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        const unsigned char *ty = sqlite3_column_text(stmt, 0);
        const unsigned char *nm = sqlite3_column_text(stmt, 1);
        const unsigned char *sq = sqlite3_column_text(stmt, 2);
        std::string type = ty ? (const char *)ty : "";
        std::string name = nm ? (const char *)nm : "";
        std::string sql = sq ? (const char *)sq : "";
        if (sql.empty()) continue;
        // lnav prints one statement per line
        std::string line;
        for (char ch : sql) {
            if (ch == '\\n') line += ' ';
            else line += ch;
        }
        while (line.size() > 1 && line[line.size() - 1] == ' ') line.pop_back();
        if (!line.empty() && line[line.size() - 1] != ';') line += ';';
        out += line + "\\n";
    }
    sqlite3_finalize(stmt);
    return out;
}''')
